    /// Runtime members whose owning run or generation is terminal.
    ///
    /// This is deliberately derived from the mission tables instead of relying on a
    /// cleanup-authored `stop` declaration. A terminal state may arrive through
    /// replication or an older client, and runtime cleanup must still converge.
    ///
    /// A member left in a superseded generation is not included. The successor generation
    /// re-owns each member it still declares and then retires the rest durably, so a member that
    /// survives a revision keeps running.
    pub fn terminal_owned_runtime_subjects(&self) -> Result<BTreeSet<String>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(TERMINAL_OWNED_RUNTIME_SUBJECTS)?;
        statement
            .query_map([], |row| row.get::<_, String>(0))?
            .collect::<Result<BTreeSet<_>, _>>()
            .map_err(Into::into)
    }

    /// Gate runners are launched directly rather than through desired declarations. Their
    /// owner is durable in the request; older mechanical/LLM requests encode it in the subject.
    pub(crate) fn mission_gate_runners(&self) -> Result<Vec<MissionGateRunner>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(
            "SELECT DISTINCT subject, origin,
                    COALESCE(json_extract(body, '$.fields.owner'),
                      'legacy:' || substr(subject, 16, instr(substr(subject, 16), '/')-1))
             FROM claims request WHERE kind='gate.requested'
               AND (json_extract(body, '$.fields.runner') IN ('exec','loop-metric')
                    OR json_extract(body, '$.fields.model') IS NOT NULL)
               AND NOT EXISTS (
                 SELECT 1 FROM claims stopped
                 WHERE stopped.subject=request.subject AND stopped.kind='runtime.observed'
                   AND json_extract(stopped.body, '$.fields.status')='stopped'
               )",
        )?;
        let mut requests = BTreeMap::<String, Vec<(String, String)>>::new();
        for row in statement.query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
            ))
        })? {
            let (subject, host, owner) = row?;
            // A runner leaves this list once its stop is observed on it.
            smallclaims::touched::note_read(|| subject.clone());
            requests.entry(owner).or_default().push((subject, host));
        }
        // New requests, and owners that finish or move on.
        for kind in [
            "gate.requested",
            "step-run.state",
            "mission-run.state",
            "run-generation.state",
        ] {
            smallclaims::touched::note_read(|| format!("kind:{kind}"));
        }
        if requests.is_empty() {
            return Ok(Vec::new());
        }
        // Match by a map rather than an OR/prefix SQL join. That join visits every step
        // for every historical gate request and stalls reconciliation as runs accumulate.
        let mut owners = connection.prepare(
            "SELECT step.subject, 'mission-run/' || run.id,
                    step.status IN ('completed','failed','cancelled')
                    OR generation.status IN ('completed','failed','cancelled','superseded')
                    OR run.phase='terminal' OR run.phase LIKE 'cleanup-%'
                    OR root.phase='terminal' OR root.phase LIKE 'cleanup-%'
             FROM step_runs step
             JOIN mission_runs run ON run.id=step.run_id
             JOIN mission_runs root ON root.id=run.root_run_id
             JOIN run_generations generation ON generation.id=step.generation_id
             UNION ALL
             SELECT 'mission-run/' || run.id, 'mission-run/' || run.id,
                    run.phase IN ('final-cancelled','terminal') OR run.phase LIKE 'cleanup-%'
                    OR run.status IN ('completed','failed','cancelled')
                    OR root.phase='terminal' OR root.phase LIKE 'cleanup-%'
             FROM mission_runs run
             JOIN mission_runs root ON root.id=run.root_run_id",
        )?;
        let mut runners = Vec::new();
        for row in owners.query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, bool>(2)?,
            ))
        })? {
            let (owner, owner_run, retired) = row?;
            for key in [owner.clone(), format!("legacy:{}", owner.replace('/', "."))] {
                if let Some(requests) = requests.get(&key) {
                    runners.extend(requests.iter().map(|(subject, host)| MissionGateRunner {
                        subject: subject.clone(),
                        host: host.clone(),
                        owner_run: owner_run.clone(),
                        retired,
                    }));
                }
            }
        }
        runners.sort_by(|left, right| left.subject.cmp(&right.subject));
        Ok(runners)
    }

    /// Observers, subscriptions, and schedules whose owner run is terminal or whose owner
    /// generation is no longer current. They must not observe, deliver, or start work.
    pub fn retired_owned_intake_subjects(&self) -> Result<BTreeSet<String>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(RETIRED_OWNED_INTAKE_SUBJECTS)?;
        statement
            .query_map([], |row| row.get::<_, String>(0))?
            .collect::<Result<BTreeSet<_>, _>>()
            .map_err(Into::into)
    }

    pub fn terminal_statuses(&self, include_history: bool) -> Result<Vec<SubjectStatus>> {
        let subjects = {
            let connection = self.readers.get();
            let mut statement = connection.prepare(
                "SELECT subject FROM desired
                 WHERE member IS NOT NULL
                   AND json_extract(member, '$.terminal')=1
                 ORDER BY subject",
            )?;
            statement
                .query_map([], |row| row.get::<_, String>(0))?
                .collect::<Result<Vec<_>, _>>()?
        };
        let mut statuses = Vec::with_capacity(subjects.len());
        for subject in subjects {
            if let Some(status) = self.status(Some(&subject))?.subjects.into_iter().next()
                && (include_history || status.projection.actionable)
            {
                statuses.push(status);
            }
        }
        Ok(statuses)
    }

    pub fn retire_eval_owned_desired(&self, run: &str) -> Result<Vec<String>> {
        let run = if run.starts_with("mission-run/") {
            run.to_owned()
        } else {
            format!("mission-run/{run}")
        };
        let run_id = run.strip_prefix("mission-run/").unwrap_or(&run);
        let mut connection = self.connection.write();
        let transaction = connection.transaction()?;
        let mode: Option<String> = transaction
            .query_row(
                "SELECT mode FROM mission_runs WHERE id=?1",
                [run_id],
                |row| row.get(0),
            )
            .optional()?;
        anyhow::ensure!(
            mode.as_deref() == Some("eval"),
            "only eval runs can retire their desired graph"
        );
        transaction.execute(
            "DELETE FROM desired
             WHERE owner_run IN (
               SELECT 'mission-run/' || id FROM mission_runs WHERE root_run_id=?1
             )",
            [run_id],
        )?;
        let residue = {
            let mut statement = transaction.prepare(
                "SELECT desired.subject
                 FROM desired
                 JOIN mission_runs
                   ON desired.owner_run='mission-run/' || mission_runs.id
                 WHERE mission_runs.root_run_id=?1
                 ORDER BY desired.subject",
            )?;
            statement
                .query_map([run_id], |row| row.get::<_, String>(0))?
                .collect::<Result<Vec<_>, _>>()?
        };
        transaction.commit()?;
        Ok(residue)
    }

    pub fn discard_desired_owned_by(&self, owner_run: &str) -> Result<usize> {
        let connection = self.connection.write();
        connection
            .execute("DELETE FROM desired WHERE owner_run=?1", [owner_run])
            .map_err(Into::into)
    }

    pub fn eval_runtime_records(&self, run: &str) -> Result<Vec<(String, bool)>> {
        let run = if run.starts_with("mission-run/") {
            run.to_owned()
        } else {
            format!("mission-run/{run}")
        };
        let run_id = run.strip_prefix("mission-run/").unwrap_or(&run);
        let connection = self.connection.write();
        let mode: Option<String> = connection
            .query_row(
                "SELECT mode FROM mission_runs WHERE id=?1",
                [run_id],
                |row| row.get(0),
            )
            .optional()?;
        anyhow::ensure!(
            mode.as_deref() == Some("eval"),
            "only eval runs have disposable runtime records"
        );

        let run_subjects = {
            let mut statement = connection.prepare(
                "SELECT id FROM mission_runs WHERE root_run_id=?1 ORDER BY created_at_unix_ms, id",
            )?;
            statement
                .query_map([run_id], |row| {
                    row.get::<_, String>(0)
                        .map(|id| format!("mission-run/{id}"))
                })?
                .collect::<Result<BTreeSet<_>, _>>()?
        };
        let mut records = BTreeMap::new();
        {
            let mut statement = connection.prepare(
                &canonical_sql("SELECT body FROM claims WHERE kind='intent.desired' ORDER BY CANONICAL_ASC(claims)"),
            )?;
            let rows = statement.query_map([], |row| row.get::<_, String>(0))?;
            for row in rows {
                let desired: DesiredSubject = serde_json::from_str(&row?)?;
                if !desired
                    .owner_run
                    .as_ref()
                    .is_some_and(|owner| run_subjects.contains(owner))
                {
                    continue;
                }
                if let Some(member) = desired.member {
                    records.insert(member.runtime_id, member.terminal);
                }
            }
        }

        let mut gate_prefixes = run_subjects
            .iter()
            .filter_map(|subject| subject.strip_prefix("mission-run/"))
            .map(|id| format!("gate-operation/mission-run.{id}/"))
            .collect::<Vec<_>>();
        {
            let mut statement = connection.prepare(
                "SELECT run_generations.id
                 FROM run_generations
                 JOIN mission_runs ON run_generations.run_id=mission_runs.id
                 WHERE mission_runs.root_run_id=?1
                 ORDER BY run_generations.created_at_unix_ms, run_generations.id",
            )?;
            let rows = statement.query_map([run_id], |row| row.get::<_, String>(0))?;
            for row in rows {
                gate_prefixes.push(format!("gate-operation/step-run.{}.", row?));
            }
        }
        {
            let mut statement = connection.prepare(
                &canonical_sql("SELECT subject, body FROM claims WHERE kind='gate.requested' ORDER BY CANONICAL_ASC(claims)"),
            )?;
            let rows = statement.query_map([], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })?;
            for row in rows {
                let (subject, body) = row?;
                if !gate_prefixes
                    .iter()
                    .any(|prefix| subject.starts_with(prefix))
                {
                    continue;
                }
                let body: Value = serde_json::from_str(&body)?;
                let fields = body.get("fields").unwrap_or(&body);
                let has_exec_runner = fields.get("runner").and_then(Value::as_str) == Some("exec")
                    || fields.get("model").and_then(Value::as_str).is_some();
                if has_exec_runner {
                    records.insert(subject.replace('/', "."), false);
                }
            }
        }
        Ok(records.into_iter().collect())
    }

    /// Search refreshes only a person's private message texts, using the same endpoint
    /// indexes as the mailbox. Other fleet writes do not invalidate this source.
    pub(crate) fn conversation_search_mail_stamp(&self, person: &str, through: u64) -> Result<String> {
        let connection = self.readers.get();
        let (count, newest): (u64, u64) = connection.query_row(
            "WITH sent AS (
                SELECT store_index FROM claims INDEXED BY claims_message_to_index
                WHERE kind='message.sent' AND json_extract(body,'$.fields.to')=?1 AND store_index<=?2
                UNION SELECT store_index FROM claims INDEXED BY claims_message_from_index
                WHERE kind='message.sent' AND json_extract(body,'$.fields.from')=?1 AND store_index<=?2
            ) SELECT COUNT(*), COALESCE(MAX(store_index),0) FROM sent",
            params![person,through],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )?;
        Ok(format!("{count}:{newest}"))
    }

    pub(crate) fn conversation_search_timeline_stamp(&self, agent: &str, incarnation: &str, through: u64) -> Result<String> {
        let connection = self.readers.get();
        let (local_count, local_newest): (u64,u64) = connection.query_row(
            "SELECT COUNT(*),COALESCE(MAX(id),0) FROM local_observations
             WHERE subject=?1 AND kind='harness.timeline'
               AND json_extract(body,'$.fields.incarnation_id')=?2 AND after_store_index<=?3", params![agent,incarnation,through],
            |row| Ok((row.get(0)?,row.get(1)?)))?;
        let (legacy_count, legacy_newest): (u64,u64) = connection.query_row(
            "SELECT COUNT(*),COALESCE(MAX(store_index),0) FROM claims
             WHERE subject=?1 AND kind='harness.timeline'
               AND json_extract(body,'$.fields.incarnation_id')=?2 AND store_index<=?3", params![agent,incarnation,through],
            |row| Ok((row.get(0)?,row.get(1)?)))?;
        Ok(format!("{local_count}:{local_newest}:{legacy_count}:{legacy_newest}"))
    }

    pub(crate) fn conversation_search_messages(&self, person: &str, through: u64) -> Result<Vec<MessageView>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(&canonical_sql(
            "WITH candidates AS (
                SELECT id FROM claims INDEXED BY claims_message_to_index
                WHERE kind='message.sent' AND json_extract(body,'$.fields.to')=?1 AND store_index<=?2
                UNION SELECT id FROM claims INDEXED BY claims_message_from_index
                WHERE kind='message.sent' AND json_extract(body,'$.fields.from')=?1 AND store_index<=?2
            ), ranked AS (
                SELECT claims.id,claims.batch_id,claims.subject,claims.store_index,claims.accepted_at_unix_ms,
                    MIN(claims.store_index) OVER (PARTITION BY claims.subject) AS created_index,
                    ROW_NUMBER() OVER (PARTITION BY claims.subject ORDER BY CANONICAL_ASC(claims)) AS ordinal
                FROM claims JOIN candidates ON candidates.id=claims.id
            ) SELECT sent.subject,sent.created_index FROM ranked AS sent
              WHERE ordinal=1 ORDER BY CANONICAL_DESC(sent) LIMIT 50001"))?;
        let rows = statement.query_map(params![person,through], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?))
        })?;
        let mut messages = Vec::new();
        for row in rows {
            let (subject, index) = row?;
            messages.push(self.message_view_cached(&connection, &subject, index)?);
        }
        Ok(messages)
    }

    pub fn messages(
        &self,
        recipient: Option<&str>,
        include_closed: bool,
    ) -> Result<Vec<MessageView>> {
        smallclaims::touched::note_read(|| match recipient {
            Some(recipient) => format!("mailbox:{recipient}"),
            None => "kind:message.sent".to_owned(),
        });
        let through = self.index()?;
        let mut after = None;
        let mut all = Vec::new();
        loop {
            let (items, next) =
                self.messages_page(recipient, include_closed, after, through, 200)?;
            all.extend(items);
            match next {
                Some(cursor) => after = Some(cursor),
                None => {
                    sort_messages_canonically(&self.readers.get(), &mut all)?;
                    // A message's lifecycle (staged, delivered, read, closed) is written on the
                    // message, not the mailbox.
                    for message in &all {
                        smallclaims::touched::note_read(|| message.subject.clone());
                    }
                    return Ok(all);
                }
            }
        }
    }

    /// The reconciler needs historical work-wake attempts, including closed
    /// ones, but not an agent's unrelated lifetime of conversation messages.
    /// First select a superset from the indexed recipient's sent claims; the
    /// final tag check keeps this equivalent to filtering the normal mailbox.
    pub fn work_wake_messages_for_reconcile(&self, agent: &str) -> Result<Vec<MessageView>> {
        let recipient = normalize_message_party(agent);
        let bare_recipient = recipient
            .strip_prefix("agent/")
            .filter(|suffix| !suffix.contains('/'))
            .unwrap_or(&recipient);
        let connection = self.readers.get();
        let mut statement = connection.prepare_cached(
            "SELECT DISTINCT sent.subject,
                    (SELECT MIN(created.store_index) FROM claims created
                     WHERE created.subject=sent.subject) AS created_index
             FROM claims sent INDEXED BY claims_message_to_index
             WHERE sent.kind='message.sent'
               AND json_extract(sent.body, '$.fields.to') IN (?1, ?2)
               AND instr(sent.body, 'st3-work:')>0
             ORDER BY created_index, sent.subject",
        )?;
        let subjects = statement
            .query_map(params![recipient, bare_recipient], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?))
            })?
            .collect::<Result<Vec<_>, _>>()?;
        drop(statement);
        let mut messages = Vec::with_capacity(subjects.len());
        for (subject, created_index) in subjects {
            let message = self.message_view_cached(&connection, &subject, created_index)?;
            if message.to == recipient
                && message.tags.iter().any(|tag| tag.starts_with("st3-work:"))
            {
                messages.push(message);
            }
        }
        sort_messages_canonically(&connection, &mut messages)?;
        smallclaims::touched::note_read(|| format!("mailbox:{recipient}"));
        smallclaims::touched::note_read(|| format!("mailbox:{bare_recipient}"));
        for message in &messages {
            smallclaims::touched::note_read(|| message.subject.clone());
        }
        Ok(messages)
    }

    pub fn message(&self, subject: &str) -> Result<Option<MessageView>> {
        let connection = self.readers.get();
        let created_index = connection.query_row(
            "SELECT MIN(store_index) FROM claims WHERE subject=?1 AND subject LIKE 'message/%'",
            [subject],
            |row| row.get::<_, Option<u64>>(0),
        )?;
        created_index
            .map(|index| self.message_view_cached(&connection, subject, index))
            .transpose()
    }

    fn message_view_cached(
        &self,
        connection: &Connection,
        subject: &str,
        created_index: u64,
    ) -> Result<MessageView> {
        // A message view depends only on its immutable subject claims and the selected
        // desired row. Unrelated graph writes must not invalidate every native mailbox.
        let mut statement = connection.prepare_cached(
            "SELECT (SELECT COALESCE(MAX(store_index), 0) FROM claims WHERE subject=?1),
                    (SELECT claim_id FROM desired WHERE subject=?1)",
        )?;
        let (latest_claim_index, desired_claim_id) = statement.query_row([subject], |row| {
            Ok((row.get::<_, u64>(0)?, row.get::<_, Option<String>>(1)?))
        })?;
        drop(statement);
        if let Some(view) = self
            .smalltalk
            .message_cache
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .get(subject)
            .filter(|entry| {
                entry.latest_claim_index == latest_claim_index
                    && entry.desired_claim_id == desired_claim_id
                    && entry.view.created_index == created_index
            })
            .map(|entry| entry.view.clone())
        {
            return Ok(view);
        }
        let view = message_view_tx(connection, subject, created_index)?;
        let mut cache = self
            .smalltalk
            .message_cache
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        if cache.len() >= MESSAGE_CACHE_LIMIT && !cache.contains_key(subject) {
            cache.clear();
        }
        cache.insert(
            subject.to_owned(),
            MessageCacheEntry {
                latest_claim_index,
                desired_claim_id,
                view: view.clone(),
            },
        );
        Ok(view)
    }

    pub fn messages_page(
        &self,
        recipient: Option<&str>,
        include_closed: bool,
        after: Option<u64>,
        through: u64,
        limit: usize,
    ) -> Result<(Vec<MessageView>, Option<u64>)> {
        let recipient = recipient.map(normalize_message_party);
        let connection = self.readers.get();
        // Native harnesses repeatedly ask for their complete durable mailbox so
        // they can reconcile delivery receipts. Start at the indexed recipient
        // claims, not every lifecycle claim for every message in the fleet.
        let fast_recipient = recipient.as_deref();
        let bare_recipient = fast_recipient.map(|value| {
            value
                .strip_prefix("agent/")
                .filter(|suffix| !suffix.contains('/'))
                .unwrap_or(value)
        });
        if let (Some(recipient), Some(bare_recipient)) = (fast_recipient, bare_recipient) {
            let mut statement = connection.prepare(
                "WITH candidates(subject) AS (
                     SELECT subject FROM claims INDEXED BY claims_message_to_index
                     WHERE kind='message.sent'
                       AND json_extract(body, '$.fields.to') IN (?1, ?2)
                     UNION
                     SELECT desired.subject FROM desired,
                            json_each(desired.body, '$.children') child
                     WHERE desired.kind='message'
                       AND json_extract(child.value, '$.name')='to'
                       AND json_extract(child.value, '$.arguments[0]') IN (?1, ?2)
                 ), created AS (
                     SELECT subject,
                            (SELECT MIN(store_index) FROM claims
                             WHERE claims.subject=candidates.subject) created_index
                     FROM candidates
                 )
                 SELECT subject, created_index FROM created
                 WHERE created_index>?3 AND created_index<=?4
                   AND (?6 OR NOT EXISTS (
                     SELECT 1 FROM claims closed
                     WHERE closed.subject=created.subject AND closed.kind='message.closed'
                   ))
                 ORDER BY created_index, subject LIMIT ?5",
            )?;
            let mut subjects = statement
                .query_map(
                    params![
                        recipient,
                        bare_recipient,
                        after.unwrap_or(0),
                        through,
                        limit.saturating_add(1),
                        include_closed,
                    ],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?)),
                )?
                .collect::<Result<Vec<_>, _>>()?;
            let has_more = subjects.len() > limit;
            subjects.truncate(limit);
            let next_after = has_more
                .then(|| subjects.last().map(|(_, index)| *index))
                .flatten();
            let mut output = Vec::new();
            for (subject, created_index) in subjects {
                let message = self.message_view_cached(&connection, &subject, created_index)?;
                if message.to == recipient && (include_closed || message.status != "closed") {
                    output.push(message);
                }
            }
            return Ok((output, next_after));
        }
        // Every recipient took the indexed path above. Without one, the message index lists the
        // open messages, or all of them, without reading their lifecycle claims.
        let mut statement = connection.prepare_cached(
            "SELECT subject, created_index FROM message_index
             WHERE (?1 OR closed=0) AND ?2 IS NULL
               AND created_index>?3 AND created_index<=?4
             ORDER BY created_index, subject LIMIT ?5",
        )?;
        let mut subjects = statement
            .query_map(
                params![
                    include_closed,
                    recipient.as_deref(),
                    after.unwrap_or(0),
                    through,
                    limit.saturating_add(1)
                ],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, u64>(1)?)),
            )?
            .collect::<Result<Vec<_>, _>>()?;
        let has_more = subjects.len() > limit;
        subjects.truncate(limit);
        let next_after = has_more
            .then(|| subjects.last().map(|(_, index)| *index))
            .flatten();
        let mut output = Vec::new();
        for (subject, created_index) in subjects {
            let message = self.message_view_cached(&connection, &subject, created_index)?;
            if recipient
                .as_deref()
                .is_none_or(|recipient| recipient == message.to)
                && (include_closed || message.status != "closed")
            {
                output.push(message);
            }
        }
        Ok((output, next_after))
    }

    pub fn operational_messages(
        &self,
        recipient: Option<&str>,
        include_history: bool,
    ) -> Result<Vec<MessageView>> {
        let messages = self.messages(recipient, include_history)?;
        Ok(if include_history {
            messages
        } else {
            selected_actionable_messages(&self.readers.get(), messages)?
        })
    }

    /// Latest member-pass fault, independently of runtime observations and unrelated diagnostics.
    pub fn member_reconcile_fault(
        &self,
        subject: &str,
        at_index: Option<u64>,
    ) -> Result<Option<String>> {
        let connection = self.readers.get();
        let body: Option<String> = connection
            .query_row(
                "SELECT body FROM claims WHERE subject=?1 AND kind='runtime.reconcile-decision'
             AND store_index<=?2 AND json_extract(body, '$.fields.key')='member-reconcile'
             ORDER BY store_index DESC LIMIT 1",
                params![subject, at_index.unwrap_or(i64::MAX as u64)],
                |row| row.get(0),
            )
            .optional()?;
        let Some(body) = body else {
            return Ok(None);
        };
        let body: Value = serde_json::from_str(&body)?;
        let fields = body.get("fields").unwrap_or(&body);
        Ok(
            (fields.get("decision").and_then(Value::as_str) == Some("member-fault")).then(|| {
                fields
                    .get("reason")
                    .and_then(Value::as_str)
                    .unwrap_or("member reconciliation failed")
                    .to_owned()
            }),
        )
    }

    /// The member fault of each of `subjects` that has one at `at_index`, as
    /// `member_reconcile_fault` reads it: one seek per subject rather than a scan of every
    /// reconcile decision the store holds.
    pub fn member_reconcile_faults_for(
        &self,
        subjects: &[String],
        at_index: u64,
    ) -> Result<BTreeMap<String, String>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare_cached(
            "SELECT body FROM claims WHERE subject=?1 AND kind='runtime.reconcile-decision'
               AND store_index<=?2 AND json_extract(body, '$.fields.key')='member-reconcile'
             ORDER BY store_index DESC LIMIT 1",
        )?;
        let mut faults = BTreeMap::new();
        for subject in subjects {
            let Some(body) = statement
                .query_row(params![subject, at_index], |row| row.get::<_, String>(0))
                .optional()?
            else {
                continue;
            };
            let body: Value = serde_json::from_str(&body)?;
            let fields = body.get("fields").unwrap_or(&body);
            if fields.get("decision").and_then(Value::as_str) == Some("member-fault") {
                faults.insert(
                    subject.clone(),
                    fields
                        .get("reason")
                        .and_then(Value::as_str)
                        .unwrap_or("member reconciliation failed")
                        .to_owned(),
                );
            }
        }
        Ok(faults)
    }

    /// Every claim and local observation of `kind` for `subject`, in log order.
    pub fn observations_for(&self, subject: &str, kind: &str) -> Result<Vec<ClaimRecord>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let mut records = self.claims_for(subject, Some(kind))?;
        let connection = self.readers.get();
        let mut statement = connection.prepare(&format!(
            "{LOCAL_OBSERVATION_COLUMNS} WHERE subject=?1 AND kind=?2 ORDER BY id"
        ))?;
        let rows = statement.query_map(params![subject, kind], |row| {
            local_observation_from_row(&self.origin, row)
        })?;
        records.extend(rows.collect::<rusqlite::Result<Vec<_>>>()?);
        records.sort_by_key(claim_log_order);
        Ok(records)
    }

    /// The newest claim or local observation of `kind` for `subject`.
    pub fn latest_observation(&self, subject: &str, kind: &str) -> Result<Option<ClaimRecord>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let claim = self.latest_claim(subject, Some(kind))?;
        let local = {
            let connection = self.readers.get();
            connection
                .query_row(
                    &format!(
                        "{LOCAL_OBSERVATION_COLUMNS} WHERE subject=?1 AND kind=?2 ORDER BY id DESC LIMIT 1"
                    ),
                    params![subject, kind],
                    |row| local_observation_from_row(&self.origin, row),
                )
                .optional()?
        };
        Ok(claim.into_iter().chain(local).max_by_key(claim_log_order))
    }

    /// Read replicated todo snapshots and their native-session bindings together at a graph
    /// snapshot. Each subject/kind lookup stops at the newest indexed claim.
    pub fn agent_todo_observations_for(
        &self,
        subjects: &[String],
        at_index: u64,
    ) -> Result<BTreeMap<String, BTreeMap<String, ClaimRecord>>> {
        if subjects.is_empty() {
            return Ok(BTreeMap::new());
        }
        let connection = self.readers.get();
        let mut statement = connection.prepare_cached(&format!(
            "SELECT {CLAIM_COLUMNS} FROM json_each(?1) subjects
             CROSS JOIN (
                 SELECT 'harness.todo.observed' AS kind
                 UNION ALL SELECT 'harness.session-file'
             ) kinds
             JOIN claims ON claims.id=(
                 SELECT claims.id FROM claims INDEXED BY claims_subject_kind_accepted_index
                 JOIN batches ON batches.id=claims.batch_id
                 WHERE claims.subject=subjects.value AND claims.kind=kinds.kind
                   AND +claims.store_index<=?2
                 ORDER BY {CANONICAL_ORDER_DESC} LIMIT 1
             )
             JOIN batches ON batches.id=claims.batch_id"
        ))?;
        let rows = statement.query_map(
            params![serde_json::to_string(subjects)?, at_index.min(i64::MAX as u64)],
            claim_from_row,
        )?;
        let mut observations = BTreeMap::<String, BTreeMap<String, ClaimRecord>>::new();
        for claim in rows {
            let claim = claim?;
            observations.entry(claim.subject.clone()).or_default()
                .insert(claim.kind.clone(), claim);
        }
        Ok(observations)
    }

    pub fn pending_observer_refresh_attempt(&self, observer: &str) -> Result<Option<String>> {
        let connection = self.readers.get();
        // The observations are listed once, not scanned for each request; see
        // `pending_subscription_mission_requests`.
        connection
            .query_row(
                &canonical_sql(
                    "SELECT json_extract(request.body, '$.fields.attempt')
                 FROM claims request
                 WHERE request.subject=?1
                   AND request.kind='observer.refresh-requested'
                   AND (
                     json_extract(request.body, '$.fields.attempt') IS NULL
                     OR json_extract(request.body, '$.fields.attempt') NOT IN (
                       SELECT json_extract(result.body, '$.fields.attempt') FROM claims result
                       WHERE result.subject=?1
                         AND result.kind IN ('observer.observed', 'observer.state')
                         AND json_extract(result.body, '$.fields.attempt') IS NOT NULL
                     )
                   )
                 ORDER BY CANONICAL_ASC(request)
                 LIMIT 1",
                ),
                [observer],
                |row| row.get(0),
            )
            .optional()
            .map_err(Into::into)
    }

    pub fn gate_request_for_owner(&self, owner: &str) -> Result<Option<ClaimRecord>> {
        let connection = self.readers.get();
        connection
            .query_row(
                &canonical_sql("SELECT id, store_index, batch_id, subject, kind, origin, actor, body, predecessors, accepted_at_unix_ms
                 FROM claims WHERE kind='gate.requested'
                 AND json_extract(body, '$.fields.owner')=?1
                 ORDER BY CANONICAL_DESC(claims) LIMIT 1"),
                [owner],
                claim_from_row,
            )
            .optional()
            .map_err(Into::into)
    }

    pub fn pending_human_reviews(&self, reviewer: Option<&str>) -> Result<Vec<HumanReviewView>> {
        let connection = self.readers.get();
        pending_human_reviews_tx(&connection, reviewer)
    }

    /// Every human gate request as (request, owner, reviewer): the episodes a human gate's
    /// attention card can name, open or long closed.
    pub fn human_gate_requests(&self) -> Result<Vec<(String, String, String)>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(
            "SELECT id, json_extract(body, '$.fields.owner'), json_extract(body, '$.fields.reviewer')
             FROM claims INDEXED BY claims_human_gate_request_index
             WHERE kind='gate.requested' AND json_extract(body, '$.fields.reviewer') IS NOT NULL
               AND json_extract(body, '$.fields.owner') IS NOT NULL",
        )?;
        statement
            .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(Into::into)
    }

    /// The reviewer's answer to the human gate request `request`, by the same rule that takes
    /// an answered request off `pending_human_reviews`.
    pub fn human_review_answer(&self, request: &str) -> Result<Option<ClaimRecord>> {
        let connection = self.readers.get();
        // An answer is written on the request's subject, its gate operation.
        smallclaims::touched::note_read(|| {
            connection
                .query_row("SELECT subject FROM claims WHERE id=?1", [request], |row| {
                    row.get(0)
                })
                .unwrap_or_default()
        });
        human_review_answer_tx(&connection, request)
    }

    /// Why `owner` has no pending human review: answered (how, by whom), stale (which of
    /// generation, revision, definition, attempt or state moved on), or never asked.
    pub fn human_review_refusal(&self, owner: &str) -> Result<String> {
        let connection = self.readers.get();
        human_review_refusal_tx(&connection, owner)
    }

    /// Request attention for a condition the daemon watches itself. The daemon closes it once
    /// that condition clears.
    /// Retained for historical import and audit fixtures. Current requests use `ask_person`.
    pub fn request_attention(
        &self,
        subject: &str,
        request: &AttentionRequest,
    ) -> Result<AttentionRequestView, St3Error> {
        self.request_attention_closing(
            subject,
            request,
            &AttentionClosing {
                closed_by: Some("st".into()),
                ..AttentionClosing::default()
            },
        )
    }

    /// Request attention that names what closes it: a target that can end, an `until` condition
    /// over its targets, a step whose end closes it, or a person. An agent's request that names
    /// none of these closes when the step that agent has claimed ends; a request with nothing
    /// that could close it is refused.
    pub fn request_attention_closing(
        &self,
        subject: &str,
        request: &AttentionRequest,
        closing: &AttentionClosing,
    ) -> Result<AttentionRequestView, St3Error> {
        let until = closing.until.as_deref();
        if let Some(closed_by) = closing.closed_by.as_deref()
            && !matches!(closed_by, "person" | "st")
        {
            return Err(St3Error::new(
                "invalid-attention-closed-by",
                format!("`{closed_by}` cannot close an attention request; use `person`"),
            ));
        }
        if let Some(until) = until {
            if !crate::model::STATUS_WAIT_CONDITIONS.contains(&until) {
                return Err(St3Error::new(
                    "invalid-attention-until",
                    format!(
                        "`{until}` is not a wait condition; use one of {}",
                        crate::model::STATUS_WAIT_CONDITIONS.join(", ")
                    ),
                ));
            }
            if request.targets.is_empty() {
                return Err(St3Error::new(
                    "invalid-attention-until",
                    "an until condition needs at least one target to watch",
                ));
            }
        }
        let reviewer = normalize_actor(&request.reviewer, "person");
        if !reviewer.starts_with("person/") {
            return Err(St3Error::new(
                "invalid-attention-reviewer",
                "an attention reviewer must be a person subject",
            ));
        }
        if request.title.trim().is_empty() || request.reason.trim().is_empty() {
            return Err(St3Error::new(
                "invalid-attention-request",
                "an attention request needs a title and a reason",
            ));
        }
        if !matches!(request.severity.as_str(), "warning" | "error") {
            return Err(St3Error::new(
                "invalid-attention-severity",
                "attention severity must be warning or error",
            ));
        }
        for target in &request.targets {
            st3_schema::registry()
                .validate_subject(target)
                .map_err(|error| St3Error::new(error.code, error.message))?;
        }
        let actor = normalize_actor(&request.actor, "agent");
        let step = attention_closing_step(&self.readers.get(), &actor, request, closing)?;
        let mut fields = BTreeMap::from([
            ("reviewer".into(), Value::String(reviewer)),
            ("title".into(), Value::String(request.title.clone())),
            ("reason".into(), Value::String(request.reason.clone())),
            ("severity".into(), Value::String(request.severity.clone())),
            (
                "targets".into(),
                Value::Array(request.targets.iter().cloned().map(Value::String).collect()),
            ),
        ]);
        if let Some(until) = until {
            fields.insert("until".into(), Value::String(until.into()));
        }
        if let Some((step, attempt)) = step {
            fields.insert("step".into(), Value::String(step));
            fields.insert("step_attempt".into(), Value::from(attempt));
        }
        if let Some(closed_by) = &closing.closed_by {
            fields.insert("closed_by".into(), Value::String(closed_by.clone()));
        }
        self.append_claim(&ClaimInput {
            subject: subject.to_owned(),
            kind: "attention.requested".into(),
            actor: Some(actor),
            fields,
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(request.idempotency_key.clone()),
        })?;
        self.attention_request(subject)
            .map_err(internal)?
            .ok_or_else(|| St3Error::new("internal", "the attention request was not stored"))
    }

    /// Historical audit closure; current attention has no independent resolution.
    pub fn resolve_attention(
        &self,
        subject: &str,
        request: &AttentionResolveRequest,
    ) -> Result<AttentionRequestView, St3Error> {
        if !matches!(request.outcome.as_str(), "resolved" | "dismissed") {
            return Err(St3Error::new(
                "invalid-attention-outcome",
                "an attention outcome must be resolved or dismissed",
            ));
        }
        let subject = if subject.starts_with("attention/") {
            subject.to_owned()
        } else {
            format!("attention/{subject}")
        };
        // Any person or agent can close any item, whoever it was routed to, so an item never
        // outlives everyone who could close it. The resolution records who closed it.
        let actor = normalize_actor(&request.actor, "person");
        if !(actor.starts_with("person/") || actor.starts_with("agent/")) {
            return Err(St3Error::new(
                "invalid-attention-resolver",
                format!("`{actor}` is neither a person nor an agent"),
            ));
        }
        let current = self
            .attention_request(&subject)
            .map_err(internal)?
            .ok_or_else(|| {
                St3Error::new(
                    "missing-attention-request",
                    format!("attention request `{subject}` does not exist"),
                )
            })?;
        self.append_claim(&ClaimInput {
            subject: subject.clone(),
            kind: "attention.resolved".into(),
            actor: Some(actor),
            fields: BTreeMap::from([
                ("request".into(), Value::String(current.request)),
                ("outcome".into(), Value::String(request.outcome.clone())),
                (
                    "reason".into(),
                    request
                        .reason
                        .clone()
                        .map(Value::String)
                        .unwrap_or(Value::Null),
                ),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(request.idempotency_key.clone()),
        })?;
        self.attention_request(&subject)
            .map_err(internal)?
            .ok_or_else(|| St3Error::new("internal", "the attention resolution was not stored"))
    }

    pub fn withdraw_attention(
        &self,
        subject: &str,
        request: &AttentionWithdrawRequest,
    ) -> Result<AttentionRequestView, St3Error> {
        if request.reason.trim().is_empty() {
            return Err(St3Error::new(
                "invalid-attention-withdrawal",
                "an attention withdrawal needs a reason",
            ));
        }
        let subject = if subject.starts_with("attention/") {
            subject.to_owned()
        } else {
            format!("attention/{subject}")
        };
        let current = self
            .attention_request(&subject)
            .map_err(internal)?
            .ok_or_else(|| {
                St3Error::new(
                    "missing-attention-request",
                    format!("attention request `{subject}` does not exist"),
                )
            })?;
        let actor = normalize_actor(&request.actor, "agent");
        if actor != current.actor {
            return Err(St3Error::new(
                "wrong-attention-requester",
                format!(
                    "attention request `{subject}` belongs to `{}`",
                    current.actor
                ),
            ));
        }
        self.append_claim(&ClaimInput {
            subject: subject.clone(),
            kind: "attention.resolved".into(),
            actor: Some(actor),
            fields: BTreeMap::from([
                ("request".into(), Value::String(current.request)),
                ("outcome".into(), Value::String("withdrawn".into())),
                ("reason".into(), Value::String(request.reason.clone())),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(request.idempotency_key.clone()),
        })?;
        self.attention_request(&subject)
            .map_err(internal)?
            .ok_or_else(|| St3Error::new("internal", "the attention withdrawal was not stored"))
    }

    pub(crate) fn resolve_attention_automatically(
        &self,
        subject: &str,
        reason: &str,
        idempotency_key: &str,
    ) -> Result<AttentionRequestView, St3Error> {
        let subject = if subject.starts_with("attention/") {
            subject.to_owned()
        } else {
            format!("attention/{subject}")
        };
        let current = self
            .attention_request(&subject)
            .map_err(internal)?
            .ok_or_else(|| {
                St3Error::new(
                    "missing-attention-request",
                    format!("attention request `{subject}` does not exist"),
                )
            })?;
        self.append_claim(&ClaimInput {
            subject: subject.clone(),
            kind: "attention.resolved".into(),
            actor: Some("daemon/runtime".into()),
            fields: BTreeMap::from([
                ("request".into(), Value::String(current.request)),
                ("outcome".into(), Value::String("resolved".into())),
                ("reason".into(), Value::String(reason.into())),
            ]),
            evidence: Vec::new(),
            expected_subject: None,
            idempotency_key: Some(idempotency_key.into()),
        })?;
        self.attention_request(&subject)
            .map_err(internal)?
            .ok_or_else(|| St3Error::new("internal", "the attention resolution was not stored"))
    }

    pub fn attention_request(&self, subject: &str) -> Result<Option<AttentionRequestView>> {
        let subject = if subject.starts_with("attention/") {
            subject.to_owned()
        } else {
            format!("attention/{subject}")
        };
        let connection = self.readers.get();
        attention_request_view_tx(&connection, &subject)
    }

    /// The current state of each fault target that has one. Resources, documents and unknown
    /// kinds have no state to show and are left out.
    pub fn attention_target_states(
        &self,
        targets: &[String],
    ) -> Result<Vec<crate::model::AttentionTargetState>> {
        let connection = self.readers.get();
        let mut states = Vec::new();
        for target in targets {
            if let Some((state, since_unix_ms)) = attention_target_state_tx(&connection, target)? {
                states.push(crate::model::AttentionTargetState {
                    id: target.clone(),
                    state,
                    since_unix_ms,
                });
            }
        }
        Ok(states)
    }

    pub fn attention_requests(
        &self,
        person: Option<&str>,
        include_resolved: bool,
    ) -> Result<Vec<AttentionRequestView>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(&canonical_sql(
            "SELECT DISTINCT subject FROM claims
             WHERE kind='attention.requested'
               AND (?1 IS NULL OR json_extract(body, '$.fields.reviewer')=?1)
             ORDER BY CANONICAL_ASC(claims)",
        ))?;
        let subjects = statement
            .query_map([person], |row| row.get::<_, String>(0))?
            .collect::<Result<Vec<_>, _>>()?;
        let requests = subjects
            .into_iter()
            .filter_map(|subject| attention_request_view_tx(&connection, &subject).transpose())
            .collect::<Result<Vec<_>, _>>()?;
        Ok(requests
            .into_iter()
            .filter(|request| include_resolved || request.status == "pending")
            .collect())
    }

    /// Pending requests that `actor` raised from `origin`, so that host can close its own alerts.
    pub fn pending_attention_requests_raised_by(
        &self,
        actor: &str,
        origin: &str,
    ) -> Result<Vec<AttentionRequestView>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(&canonical_sql(
            "SELECT request.subject FROM claims request
             WHERE request.kind='attention.requested'
               AND request.actor=?1
               AND request.origin=?2
               AND NOT EXISTS (
                 SELECT 1 FROM claims resolution
                 WHERE resolution.subject=request.subject
                   AND resolution.kind='attention.resolved'
               )
             ORDER BY CANONICAL_ASC(request)",
        ))?;
        let subjects = statement
            .query_map([actor, origin], |row| row.get::<_, String>(0))?
            .collect::<Result<Vec<_>, _>>()?;
        smallclaims::touched::note_read(|| "kind:attention.requested".to_owned());
        for subject in &subjects {
            smallclaims::touched::note_read(|| subject.clone());
        }
        subjects
            .iter()
            .filter_map(|subject| attention_request_view_tx(&connection, subject).transpose())
            .collect()
    }

    /// Current runs waiting on person steps, human gates or approvals.
    pub fn human_attention_runs(&self) -> Result<BTreeSet<String>> {
        let mut items = self.mission_run_attention_items(None)?;
        items.extend(self.person_attention_items(None, now_ms())?);
        Ok(items.into_iter().filter_map(|item| item.mission_run).collect())
    }

    /// The attention items that belong to a mission run: gate reviews, launch approvals and
    /// revision approvals. A run's header is all they read of the run.
    fn mission_run_attention_items(&self, person: Option<&str>) -> Result<Vec<AttentionItemView>> {
        let mut items = Vec::new();
        let reviews = self.pending_human_reviews(person)?;
        items.extend(reviews.into_iter().map(attention_item_from_review));

        {
            let connection = self.readers.get();
            let mut statement = connection.prepare(
                "SELECT id FROM planning_sessions
                 WHERE status='review' AND (?1 IS NULL OR requester=?1)
                 ORDER BY created_at_unix_ms, id",
            )?;
            let ids = statement
                .query_map([person], |row| row.get::<_, String>(0))?
                .collect::<Result<Vec<_>, _>>()?;
            for id in ids {
                let Some(session) = planning_session_view_tx(&connection, &id)? else {
                    continue;
                };
                let (Some(candidate), Some(preview)) = (&session.candidate, &session.preview)
                else {
                    continue;
                };
                if preview.candidate_revision != candidate.revision
                    || !preview.mission.blockers.is_empty()
                {
                    continue;
                }
                if let Some(run) = &session.target_mission_run {
                    let Some(run) = mission_run_header_tx(
                        &connection,
                        run.strip_prefix("mission-run/").unwrap_or(run),
                    )
                    .optional()?
                    else {
                        continue;
                    };
                    if session.source_generation.as_deref() != Some(run.generation.as_str())
                        || is_terminal_run_state(&run.status)
                    {
                        continue;
                    }
                }
                items.push(attention_item_from_planning(&session, candidate, preview));
            }
        }

        {
            let connection = self.readers.get();
            let mut statement = connection.prepare(
                "SELECT id FROM revision_proposals
                 WHERE status='pending-approval'
                 ORDER BY created_at_unix_ms, id",
            )?;
            let ids = statement
                .query_map([], |row| row.get::<_, String>(0))?
                .collect::<Result<Vec<_>, _>>()?;
            for id in ids {
                let proposal = revision_proposal_view_tx(&connection, &id)?;
                let run = mission_run_header_tx(
                    &connection,
                    proposal
                        .run
                        .strip_prefix("mission-run/")
                        .unwrap_or(&proposal.run),
                )
                .optional()?;
                let Some(run) = run else {
                    continue;
                };
                if run.generation != proposal.source_generation
                    || is_terminal_run_state(&run.status)
                {
                    continue;
                }
                for reviewer in proposal
                    .reviewers
                    .iter()
                    .filter(|reviewer| !proposal.approvals.contains(*reviewer))
                    .filter(|reviewer| person.is_none_or(|person| person == reviewer.as_str()))
                {
                    items.push(attention_item_from_revision(&proposal, &run, reviewer));
                }
            }
        }
        Ok(items)
    }

    pub fn attention_items(&self, person: Option<&str>) -> Result<Vec<AttentionItemView>> {
        self.attention_snapshot(person, now_ms())
    }

    /// The current faults raised for `person` under the reviewer each one names, owners aside.
    #[cfg(test)]
    pub(crate) fn fault_items(&self, person: Option<&str>) -> Result<Vec<AttentionItemView>> {
        Ok(self
            .fault_snapshot(now_ms())?
            .into_iter()
            .map(|fault| fault.item)
            .filter(|item| person.is_none_or(|person| item.person == person))
            .collect())
    }

    /// What waits on `person` and no agent can resolve: requests (person steps and agents'
    /// asks) and reviews (human gates, launch and revision approvals). Messages stay in
    /// conversations, and a fault goes to the agent that owns it, see `fault_snapshot`.
    pub fn attention_snapshot(
        &self,
        person: Option<&str>,
        as_of: u128,
    ) -> Result<Vec<AttentionItemView>> {
        let mut items = self.mission_run_attention_items(person)?;
        items.extend(self.person_attention_items(person, as_of)?);
        // A person who published a broken gate is the one to correct it.
        items.extend(
            self.broken_gate_items(person, as_of)?
                .into_iter()
                .filter(|item| item.person.starts_with("person/")),
        );
        self.current_attention(items, as_of)
    }

    /// Every current fault, each with the agent that owns it: the agent assigned to the failed
    /// step, else the run's requester when that is an agent, else the fleet's fault agent. No
    /// fault is a person's: the owning agent retries, revises or cancels, and asks a person
    /// only for what only a person can give.
    pub fn fault_snapshot(&self, as_of: u128) -> Result<Vec<FaultView>> {
        let mut items = self.subscription_fault_items(as_of)?;
        items.extend(self.operational_attention_items(None, as_of)?);
        items.extend(
            self.broken_gate_items(None, as_of)?
                .into_iter()
                .filter(|item| !item.person.starts_with("person/")),
        );
        items.extend(self.checkpoint_attention_items(None, as_of)?);
        let fallback = self.fleet_fault_agent()?;
        self.current_attention(items, as_of)?
            .into_iter()
            .map(|item| {
                Ok(FaultView {
                    owner: self.fault_owner(&item, fallback.as_deref())?,
                    item,
                })
            })
            .collect()
    }

    fn subscription_fault_items(&self, as_of: u128) -> Result<Vec<AttentionItemView>> {
        let mut items = Vec::new();
        {
            let connection = self.readers.get();
            let mut statement = connection.prepare(
                &canonical_sql("SELECT id, store_index, batch_id, subject, kind, origin, actor, body,
                        predecessors, accepted_at_unix_ms
                 FROM claims WHERE kind='subscription.mission-failed' ORDER BY CANONICAL_ASC(claims)"),
            )?;
            let failures = statement
                .query_map([], claim_from_row)?
                .collect::<Result<Vec<_>, _>>()?;
            for failure in failures {
                if failure.accepted_at_unix_ms > as_of
                    || !person_work::declaration_live(&connection, &failure.subject)?
                    || !subscription_failure_is_current_tx(&connection, &failure)?
                {
                    continue;
                }
                let fields = failure.body.get("fields").unwrap_or(&failure.body);
                let request = fields
                    .get("request")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                let requester: Option<String> = connection
                    .query_row(
                        "SELECT json_extract(body, '$.fields.requester') FROM claims WHERE id=?1",
                        [request],
                        |row| row.get(0),
                    )
                    .optional()?
                    .flatten();
                let reviewer = requester
                    .filter(|value| value.starts_with("person/"))
                    .unwrap_or_else(|| "person/operator".into());
                let code = fields
                    .get("code")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                let reason = fields
                    .get("reason")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                items.push(AttentionItemView {
                    episode: failure.id.clone(),
                    priority: "high".into(),
                    kind: "fault".into(),
                    review_mode: None,
                    subject: failure.subject.clone(),
                    person: reviewer,
                    // st's subscription observer raised it.
                    requester_id: Some(
                        failure
                            .actor
                            .clone()
                            .unwrap_or_else(|| "agent/st3/reconciler".into()),
                    ),
                    launch_id: None,
                    variant_id: None,
                    message_id: None,
                    title: "Subscription mission failed".into(),
                    detail: format!("{code}: {reason}"),
                    mission: None,
                    mission_run: None,
                    step: None,
                    targets: vec![failure.subject.clone()],
                    requested_at_unix_ms: failure.accepted_at_unix_ms,
                    actions: vec![attention_action(
                        "inspect subscription",
                        &["st", "subject", &failure.subject],
                    )],
                    request: None,
                });
            }
        }
        Ok(items)
    }

    /// Keep the items requested by `as_of` whose run is still current, then order them.
    fn current_attention(
        &self,
        mut items: Vec<AttentionItemView>,
        as_of: u128,
    ) -> Result<Vec<AttentionItemView>> {
        let connection = self.readers.get();
        items.retain(|item| item.requested_at_unix_ms <= as_of);
        let mut live = Vec::new();
        for mut item in items {
            if let Some(run) = item.mission_run.as_deref() {
                if !person_work::run_live(&connection, run, None, item.kind == "fault")? {
                    continue;
                }
            }
            if item.episode.is_empty() {
                item.episode = connection
                    .query_row(
                        &canonical_sql(
                            "SELECT id FROM claims WHERE subject=?1
                    ORDER BY CANONICAL_DESC(claims) LIMIT 1",
                        ),
                        [&item.subject],
                        |row| row.get::<_, String>(0),
                    )
                    .optional()?
                    .unwrap_or_else(|| item.subject.clone());
            }
            live.push(item);
        }
        let priority = |item: &AttentionItemView| match item.priority.as_str() {
            "critical" => 0,
            "high" => 1,
            "normal" => 2,
            _ => 3,
        };
        live.sort_by(|left, right| {
            priority(left)
                .cmp(&priority(right))
                .then_with(|| left.requested_at_unix_ms.cmp(&right.requested_at_unix_ms))
                .then_with(|| left.subject.cmp(&right.subject))
                .then_with(|| left.person.cmp(&right.person))
                .then_with(|| left.episode.cmp(&right.episode))
        });
        let items = live;
        Ok(items)
    }

    pub fn selected_desired_token(&self, subject: &str) -> Result<Option<String>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let connection = self.readers.get();
        current_desired_row(&connection, subject).map(|row| row.map(|row| row.claim_id))
    }

    /// The selected desired revision of `subject`, then each predecessor that differs from it
    /// only in presentation. The last entry is the revision that still defines the launch, so
    /// launch records, restart budgets, and crash-loop parking follow a rename.
    pub fn launch_lineage(&self, subject: &str) -> Result<Vec<String>> {
        let connection = self.readers.get();
        launch_lineage_tx(&connection, subject)
    }

    /// `selected_desired_token` of each of `subjects` that has a declaration, in one statement.
    pub fn selected_desired_tokens(&self, subjects: &[&str]) -> Result<BTreeMap<String, String>> {
        let connection = self.readers.get();
        connection
            .prepare_cached(
                "SELECT subject, claim_id FROM desired
                 WHERE subject IN (SELECT value FROM json_each(?1))",
            )?
            .query_map([serde_json::to_string(subjects)?], |row| {
                Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
            })?
            .collect::<Result<BTreeMap<_, _>, _>>()
            .map_err(Into::into)
    }

    pub fn selected_desired_revision(&self, subject: &str) -> Result<Option<String>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let connection = self.readers.get();
        current_desired_row(&connection, subject).map(|row| row.map(|row| row.revision))
    }

    pub fn selected_desired_kind(&self, subject: &str) -> Result<Option<String>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let connection = self.readers.get();
        current_desired_row(&connection, subject).map(|row| row.map(|row| row.kind))
    }

    pub fn selected_desired_origin(&self, subject: &str) -> Result<Option<String>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let connection = self.readers.get();
        connection
            .query_row(
                "SELECT claims.origin FROM desired
                 JOIN claims ON claims.id=desired.claim_id
                 WHERE desired.subject=?1",
                [subject],
                |row| row.get(0),
            )
            .optional()
            .map_err(Into::into)
    }

    /// The origin used to attribute a runtime to its owner. This deliberately follows
    /// `selected_actual_source_at`'s preference for a runtime observation over later
    /// non-runtime claims, without reducing the subject's entire history.
    pub fn selected_actual_origin(&self, subject: &str) -> Result<Option<String>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let connection = self.readers.get();
        // Walk the accepted-time index newest first: sorting every runtime observation of the
        // subject cost each settled stop, checked on every pass, a tenth of a millisecond.
        let runtime_origin = connection
            .prepare_cached(&format!(
                "{} LIMIT 1",
                newest_claims_of_kind_query("claims.origin", "runtime.observed")
            ))?
            .query_row(params![subject, i64::MAX as u64], |row| row.get(0))
            .optional()?;
        if runtime_origin.is_some() {
            return Ok(runtime_origin);
        }
        connection
            .query_row(
                &canonical_sql(
                    "SELECT origin FROM claims
                 WHERE subject=?1 AND kind!='intent.desired'
                   AND kind NOT LIKE 'harness.%'
                   AND kind!='runtime.readiness-deadline-reached'
                   AND kind!='reconcile.fault'
                 ORDER BY CANONICAL_DESC(claims) LIMIT 1",
                ),
                [subject],
                |row| row.get(0),
            )
            .optional()
            .map_err(Into::into)
    }

    #[allow(clippy::too_many_arguments)]
    pub fn record_resource_observation(
        &self,
        observer: &str,
        desired_revision: &str,
        attempt: Option<&str>,
        resource: &str,
        cursor: Option<&str>,
        facts: &Value,
        next_check_unix_ms: u128,
        subscriptions: &[(String, SubscriptionSpec)],
    ) -> Result<ResourceObservationOutcome, St3Error> {
        let facts = canonical_json_value(facts);
        let operation_hash = canonical_hash(&(
            observer,
            desired_revision,
            attempt,
            cursor,
            &facts,
            next_check_unix_ms,
        ))
        .map_err(internal)?;
        let idempotency_key = format!("resource-observation:{operation_hash}");
        self.connection
            .batched(|transaction| -> Result<ResourceObservationOutcome, St3Error> {
                if let Some(response) = transaction
                    .query_row(
                        "SELECT response FROM idempotency WHERE operation_id=?1",
                        [opaque_cache_key(&idempotency_key)],
                        |row| row.get::<_, String>(0),
                    )
                    .optional()
                    .map_err(internal)?
                {
                    return serde_json::from_str(&response).map_err(internal);
                }
                let current_observer = current_desired_row_tx(transaction, observer).map_err(internal)?;
                if current_observer
                    .as_ref()
                    .map(|desired| desired.revision.as_str())
                    != Some(desired_revision)
                {
                    return Err(St3Error::new(
                        "stale-observer-revision",
                        format!("observer `{observer}` changed before its observation completed"),
                    ));
                }
                let mut active_subscriptions = Vec::new();
                for (subject, expected) in subscriptions {
                    let Some(desired) = current_desired_row_tx(transaction, subject).map_err(internal)?
                    else {
                        continue;
                    };
                    if desired.kind != "subscription" {
                        continue;
                    }
                    let value = serde_json::from_str(&desired.body).map_err(internal)?;
                    if crate::graph::subscription_spec(&value).as_ref() == Some(expected)
                        && !expected.stopped
                    {
                        active_subscriptions.push((subject.clone(), expected.clone()));
                    }
                }
                let normalized_observation = normalize_resource_observation(
                    transaction,
                    &ClaimInput {
                        subject: resource.into(),
                        kind: "resource.observed".into(),
                        actor: None,
                        fields: BTreeMap::from([("facts".into(), facts.clone())]),
                        evidence: Vec::new(),
                        expected_subject: None,
                        idempotency_key: None,
                    },
                )?
                .expect("a resource observation is normalized");
                let resource_kind = normalized_observation
                    .get("kind")
                    .cloned()
                    .expect("a normalized resource observation has a kind");
                let facts = normalized_observation
                    .get("facts")
                    .expect("a normalized resource observation has facts");
                let previous = latest_actual(transaction, resource)
                    .map_err(internal)?
                    .and_then(|actual| actual.get("facts").cloned());
                let baseline = previous.is_none();
                let previous_object = previous.as_ref().and_then(Value::as_object);
                let current_object = facts.as_object().ok_or_else(|| {
                    St3Error::new(
                        "invalid-resource-observation",
                        "resource observation facts must be an object",
                    )
                })?;
                // A repository's collections name the items an observation saw. Each item is its
                // own resource, so the repository resource keeps only its own facts and a change
                // to one item records only that item.
                let collection = |field: &str| {
                    REPOSITORY_COLLECTIONS
                        .iter()
                        .any(|(name, _, _)| *name == field)
                };
                let repository_facts = Value::Object(
                    current_object
                        .iter()
                        .filter(|(field, _)| !collection(field))
                        .map(|(field, value)| (field.clone(), value.clone()))
                        .collect(),
                );
                let legacy_collections = previous_object
                    .is_some_and(|previous| previous.keys().any(|field| collection(field)));
                let mut changed_fields = BTreeSet::new();
                for field in current_object
                    .keys()
                    .chain(previous_object.into_iter().flat_map(serde_json::Map::keys))
                    .filter(|field| !collection(field))
                {
                    if previous_object.and_then(|object| object.get(field)) != current_object.get(field) {
                        changed_fields.insert(field.clone());
                    }
                }
                let repository_changed_fields = changed_fields.iter().cloned().collect::<Vec<_>>();
                let mut recorded_items = HashMap::new();
                for (field, segment, _) in REPOSITORY_COLLECTIONS {
                    for number in current_object
                        .get(field)
                        .and_then(Value::as_array)
                        .into_iter()
                        .flatten()
                        .filter_map(|item| item.get("number").and_then(Value::as_u64))
                    {
                        let subject = format!("{resource}/{segment}/{number}");
                        let recorded = latest_actual(transaction, &subject)
                            .map_err(internal)?
                            .and_then(|actual| actual.get("facts").cloned());
                        let observed_at = transaction
                            .query_row(
                                &canonical_sql(
                                    "SELECT accepted_at_unix_ms FROM claims
                                     WHERE subject=?1 AND kind='resource.observed'
                                     ORDER BY CANONICAL_DESC(claims) LIMIT 1",
                                ),
                                [&subject],
                                |row| row.get::<_, String>(0),
                            )
                            .optional()
                            .map_err(internal)?
                            .and_then(|at| at.parse::<u128>().ok())
                            .unwrap_or_default();
                        recorded_items.insert(subject, recorded.map(|facts| (facts, observed_at)));
                    }
                }
                let mut discovered = Vec::new();
                for (field, _, _) in REPOSITORY_COLLECTIONS {
                    let items = discovered_collection_items(
                        resource,
                        field,
                        previous.as_ref(),
                        &facts,
                        &mut |subject| {
                            recorded_items
                                .get(subject)
                                .cloned()
                                .flatten()
                                .map(|(facts, _)| facts)
                        },
                    );
                    changed_fields.extend(items.iter().flat_map(|item| item.data_types.iter().cloned()));
                    discovered.extend(items.into_iter().map(|item| (field, item)));
                }
                let changed_fields = changed_fields.into_iter().collect::<Vec<_>>();
                let observer_health_is_current = latest_actual(transaction, observer)
                    .map_err(internal)?
                    .is_some_and(|actual| {
                        actual.get("state").and_then(Value::as_str) == Some("healthy")
                            && actual.get("revision").and_then(Value::as_str) == Some(desired_revision)
                            && actual.get("reason").is_none()
                    });
                let mut subscription_states = BTreeMap::new();
                for (subscription_subject, subscription) in &active_subscriptions {
                    let target_exists = if subscription.delivery == "message" {
                        transaction
                            .query_row(
                                "SELECT 1 FROM desired WHERE subject=?1 AND kind='agent'",
                                [&subscription.to],
                                |_| Ok(()),
                            )
                            .optional()
                            .map_err(internal)?
                            .is_some()
                    } else {
                        true
                    };
                    let status = if target_exists { "active" } else { "pending" };
                    let current_status = latest_actual(transaction, subscription_subject)
                        .map_err(internal)?
                        .and_then(|actual| {
                            actual
                                .get("state")
                                .and_then(Value::as_str)
                                .map(str::to_owned)
                        });
                    subscription_states.insert(
                        subscription_subject.clone(),
                        (
                            target_exists,
                            status,
                            current_status.as_deref() != Some(status),
                        ),
                    );
                }
                let changed = baseline || !changed_fields.is_empty() || !discovered.is_empty();
                let should_record = changed
                    || legacy_collections
                    || attempt.is_some()
                    || !observer_health_is_current
                    || subscription_states.values().any(|(_, _, changed)| *changed);
                if !should_record {
                    return Ok(ResourceObservationOutcome {
                        baseline,
                        changed_fields,
                        observation_claim: None,
                        message_subjects: Vec::new(),
                    });
                }
                let now = write_time(transaction, &self.origin).map_err(internal)?;
                let sequence = next_replica_sequence(transaction, &self.origin).map_err(internal)?;
                let previous_hash = previous_batch_hash(transaction, &self.origin).map_err(internal)?;
                let batch_hash = batch_header_hash(&self.origin, sequence, previous_hash.as_deref(), now)
                    .map_err(internal)?;
                let batch_id = format!("batch/{}/{sequence}/{batch_hash}", self.origin);
                transaction
                    .execute(
                        "INSERT INTO batches(id, origin, replica_sequence, previous_hash, hash, accepted_at_unix_ms)
                         VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
                        params![
                            batch_id,
                            self.origin,
                            sequence,
                            previous_hash,
                            batch_hash,
                            now.to_string()
                        ],
                    )
                    .map_err(internal)?;
                let observer_predecessors = latest_claim_id_tx(transaction, observer)
                    .map_err(internal)?
                    .into_iter()
                    .collect::<Vec<_>>();
                if !observer_health_is_current {
                    append_claim_tx(
                        transaction,
                        &self.origin,
                        observer,
                        "observer.state",
                        None,
                        &json!({"fields": {
                            "state": "healthy",
                            "revision": desired_revision,
                        }}),
                        &observer_predecessors,
                        Some(&batch_id),
                    )
                    .map_err(internal)?;
                }
                if changed || attempt.is_some() {
                    let observer_predecessors = latest_claim_id_tx(transaction, observer)
                        .map_err(internal)?
                        .into_iter()
                        .collect::<Vec<_>>();
                    let mut observer_fields = json!({
                        "status": "healthy",
                        "revision": desired_revision,
                        "cursor": cursor,
                        "changed": changed,
                    });
                    if let Some(attempt) = attempt {
                        observer_fields
                            .as_object_mut()
                            .expect("observer fields are an object")
                            .insert("attempt".into(), Value::String(attempt.into()));
                    }
                    append_claim_tx(
                        transaction,
                        &self.origin,
                        observer,
                        "observer.observed",
                        None,
                        &json!({"fields": observer_fields}),
                        &observer_predecessors,
                        Some(&batch_id),
                    )
                    .map_err(internal)?;
                }
                // Builds before item resources kept every item in the repository facts. The first
                // observation without them records the repository's own facts once more.
                let observation_claim = if baseline
                    || !repository_changed_fields.is_empty()
                    || legacy_collections
                {
                    let predecessors = latest_claim_id_tx(transaction, resource)
                        .map_err(internal)?
                        .into_iter()
                        .collect::<Vec<_>>();
                    Some(
                        append_claim_tx(
                            transaction,
                            &self.origin,
                            resource,
                            "resource.observed",
                            None,
                            &json!({"fields": {
                                "kind": resource_kind,
                                "facts": repository_facts,
                                "observer": observer,
                                "baseline": baseline,
                                "changed_fields": repository_changed_fields,
                            }}),
                            &predecessors,
                            Some(&batch_id),
                        )
                        .map_err(internal)?,
                    )
                } else {
                    None
                };
                let mut collection_discoveries = BTreeMap::<String, Vec<(String, String)>>::new();
                let mut item_claims = Vec::new();
                let mut item_mentions = Vec::new();
                for (field, item) in discovered {
                    let DiscoveredItem {
                        subject,
                        kind,
                        facts: mut item_facts,
                        changed_fields: item_changed_fields,
                        data_types,
                        deliver,
                    } = item;
                    // An agent's checkout names the opener first. An authoring run's own pull
                    // request resource names the run when no agent was found.
                    if deliver
                        && field == "pull_requests"
                        && item_facts.get("opened_by").is_none()
                        && item_facts.get("opened_by_run").is_none()
                        && let Some(run) = authoring_pull_request_runs_tx(transaction, &item_facts)
                            .map_err(internal)?
                            .into_iter()
                            .next()
                    {
                        item_facts["opened_by_run"] = Value::String(run);
                    }
                    // A pull request item already keeps its recorded opener: its facts are laid
                    // over the recorded ones, and opener attribution keeps a named opener.
                    if kind == "vcs.issue" {
                        let normalized = normalize_resource_observation(
                            transaction,
                            &ClaimInput {
                                subject: subject.clone(),
                                kind: "resource.observed".into(),
                                actor: None,
                                fields: BTreeMap::from([
                                    ("kind".into(), Value::String(kind.into())),
                                    ("facts".into(), item_facts),
                                ]),
                                evidence: Vec::new(),
                                expected_subject: None,
                                idempotency_key: None,
                            },
                        )?
                        .expect("an issue observation is normalized");
                        item_facts = normalized["facts"].clone();
                    }
                    let predecessors = latest_claim_id_tx(transaction, &subject)
                        .map_err(internal)?
                        .into_iter()
                        .collect::<Vec<_>>();
                    let evidence = observation_claim
                        .as_ref()
                        .map(|claim| vec![claim.id.clone()])
                        .unwrap_or_default();
                    let claim = append_claim_tx(
                        transaction,
                        &self.origin,
                        &subject,
                        "resource.observed",
                        None,
                        &json!({"fields": {
                            "kind": kind,
                            "facts": item_facts,
                            "observer": observer,
                            "baseline": false,
                            "changed_fields": item_changed_fields,
                        }, "evidence": evidence}),
                        &predecessors,
                        Some(&batch_id),
                    )
                    .map_err(internal)?;
                    if !data_types.is_empty() {
                        let prior = recorded_items.get(&subject).cloned().flatten();
                        let mentions = if data_types.contains("mentions") {
                            new_mentions(prior.as_ref(), &item_facts)
                        } else {
                            Vec::new()
                        };
                        item_mentions.push((subject.clone(), claim.id.clone(), item_facts.clone(), mentions));
                        item_claims.push((data_types, subject.clone(), claim.id.clone(), item_facts));
                    }
                    if deliver {
                        collection_discoveries
                            .entry(field.into())
                            .or_default()
                            .push((subject, claim.id));
                    }
                }
                let mut available_subscriptions = BTreeSet::new();
                for (subscription_subject, _) in &active_subscriptions {
                    let (target_exists, status, status_changed) = subscription_states
                        .get(subscription_subject)
                        .copied()
                        .expect("an active subscription has a computed state");
                    if status_changed {
                        let predecessors = latest_claim_id_tx(transaction, subscription_subject)
                            .map_err(internal)?
                            .into_iter()
                            .collect::<Vec<_>>();
                        append_claim_tx(
                            transaction,
                            &self.origin,
                            subscription_subject,
                            "subscription.state",
                            None,
                            &json!({"fields": {
                                "state": status,
                                "reason": (!target_exists).then_some("the delivery target is absent"),
                            }}),
                            &predecessors,
                            Some(&batch_id),
                        )
                        .map_err(internal)?;
                    }
                    if target_exists {
                        available_subscriptions.insert(subscription_subject.clone());
                    }
                }
                let mut message_subjects = Vec::new();
                // Each watch on an item this observation changed hears the comments and reviews it
                // did not know, a move of the required checks into pass or fail, and the close
                // that ends it, each as one wake. The baseline tells no watch anything.
                if !baseline {
                    for (subscription_subject, subscription) in &active_subscriptions {
                        let Some(watch) = &subscription.watch else {
                            continue;
                        };
                        if !available_subscriptions.contains(subscription_subject)
                            || watch.until_unix_ms.is_some_and(|until| until <= now_ms())
                            || watch_ended_tx(transaction, subscription_subject, watch)?.is_some()
                        {
                            continue;
                        }
                        let Some((_, item_subject, item_claim, item_facts)) =
                            item_claims.iter().find(|(_, subject, ..)| {
                                subject.rsplit('/').next().and_then(|number| number.parse().ok())
                                    == Some(watch.item)
                            })
                        else {
                            continue;
                        };
                        let Some((thread, _)) = crate::github_watch::watch_parts(subscription_subject)
                        else {
                            continue;
                        };
                        let prior = recorded_items
                            .get(item_subject)
                            .cloned()
                            .flatten()
                            .map(|(facts, _)| facts);
                        let seen = REPOSITORY_COLLECTIONS
                            .iter()
                            .filter_map(|(field, _, _)| current_object.get(*field).and_then(Value::as_array))
                            .flatten()
                            .find(|item| item.get("number").and_then(Value::as_u64) == Some(watch.item))
                            .cloned()
                            .unwrap_or(Value::Null);
                        for event in crate::github_watch::watch_events(
                            watch,
                            prior.as_ref(),
                            &seen,
                            item_facts,
                        ) {
                            let posted_by = match &event {
                                crate::github_watch::WatchEvent::Comment(entry) => {
                                    github_posted_by_tx(transaction, &thread, entry)?
                                }
                                _ => None,
                            };
                            // A seat never wakes for what it posted.
                            if posted_by.as_deref() == Some(subscription.to.as_str()) {
                                continue;
                            }
                            let wake = crate::github_watch::wake(
                                subscription_subject,
                                watch,
                                &thread,
                                item_facts,
                                &event,
                                item_claim,
                                posted_by.as_deref(),
                            )?;
                            let ended = matches!(event, crate::github_watch::WatchEvent::Ended { .. });
                            if latest_claim_id_tx(transaction, &wake.subject)
                                .map_err(internal)?
                                .is_none()
                            {
                                append_claim_tx(
                                    transaction,
                                    &self.origin,
                                    &wake.subject,
                                    "message.sent",
                                    None,
                                    &json!({"fields": {
                                        "from": format!("daemon/{}", self.origin),
                                        "to": subscription.to,
                                        "title": wake.title,
                                        "content": wake.content,
                                        "status": "sent",
                                        "tags": wake.tags,
                                    }, "evidence": [item_claim]}),
                                    &[],
                                    Some(&batch_id),
                                )
                                .map_err(claim_append_error)?;
                                message_subjects.push(wake.subject.clone());
                            }
                            if ended {
                                let merged = matches!(
                                    event,
                                    crate::github_watch::WatchEvent::Ended { merged: true }
                                );
                                end_watch_tx(
                                    transaction,
                                    &self.origin,
                                    Some(&batch_id),
                                    subscription_subject,
                                    watch,
                                    if merged { "merged" } else { "closed" },
                                    Some(&wake.subject),
                                )?;
                            }
                        }
                    }
                }
                if !baseline && !changed_fields.is_empty() {
                    let evidence = observation_claim
                        .as_ref()
                        .map(|claim| vec![claim.id.clone()])
                        .unwrap_or_default();
                    for (subscription_subject, subscription) in &active_subscriptions {
                        if !available_subscriptions.contains(subscription_subject)
                            || subscription.watch.is_some()
                        {
                            continue;
                        }
                        let selected = changed_fields
                            .iter()
                            .filter(|field| subscription.fields.contains(field))
                            .cloned()
                            .collect::<Vec<_>>();
                        if selected.is_empty() {
                            continue;
                        }
                        if let Some(condition) = &subscription.condition {
                            let condition_is_true =
                                subscription_condition_matches(condition, &repository_facts);
                            let condition_was_true = previous
                                .as_ref()
                                .is_some_and(|facts| subscription_condition_matches(condition, facts));
                            if !condition_is_true || condition_was_true {
                                continue;
                            }
                        }
                        let selected_items = item_claims
                            .iter()
                            .filter(|(data_types, ..)| selected.iter().any(|name| data_types.contains(name)))
                            .collect::<Vec<_>>();
                        let stable = if selected_items.is_empty() {
                            canonical_hash(&(
                                observation_claim.as_ref().map(|claim| claim.id.as_str()),
                                subscription_subject,
                            ))
                        } else {
                            canonical_hash(&(
                                observation_claim.as_ref().map(|claim| claim.id.as_str()),
                                subscription_subject,
                                selected_items
                                    .iter()
                                    .map(|(_, _, claim, _)| claim.as_str())
                                    .collect::<Vec<_>>(),
                            ))
                        }
                        .map_err(internal)?;
                        // A batched message collects new items and mentions until the reconciler
                        // sends them together, at most once per interval.
                        if subscription.delivery == "message" && subscription.batch_every_ms.is_some() {
                            let repository_identity = current_object
                                .get("repository_id")
                                .filter(|value| !value.is_null())
                                .cloned()
                                .unwrap_or_else(|| Value::String(resource.into()));
                            let entries = batch_entries_tx(
                                transaction,
                                &self.origin,
                                &batch_id,
                                subscription_subject,
                                subscription,
                                &subscription.to,
                                &repository_identity,
                                &selected,
                                &collection_discoveries,
                                &item_claims,
                                &item_mentions,
                                &mut message_subjects,
                            )?;
                            if entries.is_empty() {
                                continue;
                            }
                            let delivery_key = canonical_hash(&(
                                "batched",
                                &subscription.to,
                                subscription_subject.rsplit('/').next(),
                                entries.iter().map(|(key, ..)| key.as_str()).collect::<Vec<_>>(),
                            ))
                            .map_err(internal)?;
                            let recorded = transaction
                                .query_row(
                                    "SELECT 1 FROM claims WHERE kind='subscription.batched'
                                     AND json_extract(body, '$.fields.delivery_key')=?1 LIMIT 1",
                                    [&delivery_key],
                                    |_| Ok(()),
                                )
                                .optional()
                                .map_err(internal)?
                                .is_some();
                            if !recorded {
                                append_claim_tx(
                                    transaction,
                                    &self.origin,
                                    subscription_subject,
                                    "subscription.batched",
                                    None,
                                    &json!({"fields": {
                                        "entries": entries.iter().map(|(_, _, entry)| entry).collect::<Vec<_>>(),
                                        "delivery_key": delivery_key,
                                    }, "evidence": entries.iter().map(|(_, claim, _)| claim).collect::<Vec<_>>()}),
                                    &[],
                                    Some(&batch_id),
                                )
                                .map_err(claim_append_error)?;
                            }
                            continue;
                        }
                        // A batched delivery reaches one agent per observation, never a person
                        // directly: one request carries every new pull request head, new issue,
                        // and new mention of the named logins on items no live agent owns, so the
                        // mission's agent can group, summarize, and ask once. An owned item goes
                        // to its owner.
                        if subscription.delivery == "mission"
                            && let Some(text_input) = subscription.text_input.as_deref()
                        {
                            let (Some(mission), Some(resource_input), Some(workspace)) = (
                                subscription.mission.as_deref(),
                                subscription.resource_input.as_deref(),
                                subscription.workspace.as_deref(),
                            ) else {
                                continue;
                            };
                            let repository_identity = current_object
                                .get("repository_id")
                                .filter(|value| !value.is_null())
                                .cloned()
                                .unwrap_or_else(|| Value::String(resource.into()));
                            let delivery_scope = subscription_subject
                                .rsplit('/')
                                .next()
                                .expect("a subscription subject has a local name");
                            let unowned = batch_entries_tx(
                                transaction,
                                &self.origin,
                                &batch_id,
                                subscription_subject,
                                subscription,
                                mission,
                                &repository_identity,
                                &selected,
                                &collection_discoveries,
                                &item_claims,
                                &item_mentions,
                                &mut message_subjects,
                            )?;
                            if unowned.is_empty() {
                                continue;
                            }
                            let delivery_key = canonical_hash(&(
                                "batch",
                                mission,
                                delivery_scope,
                                unowned.iter().map(|(key, ..)| key.as_str()).collect::<Vec<_>>(),
                            ))
                            .map_err(internal)?;
                            let requested = transaction
                                .query_row(
                                    "SELECT 1 FROM claims WHERE kind='subscription.mission-requested'
                                     AND json_extract(body, '$.fields.delivery_key')=?1 LIMIT 1",
                                    [&delivery_key],
                                    |_| Ok(()),
                                )
                                .optional()
                                .map_err(internal)?
                                .is_some();
                            // The run pins the repository's latest observation as its source.
                            let Some(discovery) = observation_claim
                                .as_ref()
                                .map(|claim| claim.id.clone())
                                .or(latest_claim_id_tx(transaction, resource).map_err(internal)?)
                            else {
                                continue;
                            };
                            if requested {
                                continue;
                            }
                            let mut request_fields = json!({
                                "mission": format!("mission/{mission}"),
                                "resource": resource,
                                "resource_input": resource_input,
                                "workspace": workspace,
                                "discovery": discovery,
                                "delivery_key": delivery_key,
                                "text_input": text_input,
                                "text": serde_json::to_string(
                                    &unowned.iter().map(|(_, _, mention)| mention).collect::<Vec<_>>()
                                ).map_err(internal)?,
                            });
                            if let Some(revision) = subscription.revision.as_deref() {
                                request_fields["mission_revision"] = Value::String(revision.into());
                            }
                            if let Some(requester) = subscription.requester.as_deref() {
                                request_fields["requester"] = Value::String(requester.into());
                            }
                            append_claim_tx(
                                transaction,
                                &self.origin,
                                subscription_subject,
                                "subscription.mission-requested",
                                None,
                                &json!({"fields": request_fields, "evidence": unowned
                                    .iter()
                                    .map(|(_, claim, _)| claim.clone())
                                    .collect::<Vec<_>>()}),
                                &[],
                                Some(&batch_id),
                            )
                            .map_err(claim_append_error)?;
                            continue;
                        }
                        if subscription.delivery == "mission" {
                            let Some(mission) = subscription.mission.as_deref() else {
                                continue;
                            };
                            let Some(resource_input) = subscription.resource_input.as_deref() else {
                                continue;
                            };
                            let Some(workspace) = subscription.workspace.as_deref() else {
                                continue;
                            };
                            let uses_collection = selected
                                .iter()
                                .any(|field| matches!(field.as_str(), "pull_requests" | "issues"));
                            let discoveries = if uses_collection {
                                selected
                                    .iter()
                                    .flat_map(|field| {
                                        collection_discoveries
                                            .get(field)
                                            .into_iter()
                                            .flatten()
                                            .cloned()
                                    })
                                    .collect::<Vec<_>>()
                            } else {
                                observation_claim
                                    .as_ref()
                                    .map(|claim| vec![(resource.to_owned(), claim.id.clone())])
                                    .unwrap_or_default()
                            };
                            for (delivery_resource, discovery) in discoveries {
                                let discovery_body = transaction
                                    .query_row("SELECT body FROM claims WHERE id=?1", [&discovery], |row| {
                                        row.get::<_, String>(0)
                                    })
                                    .map_err(internal)?;
                                let discovery_body: Value =
                                    serde_json::from_str(&discovery_body).map_err(internal)?;
                                let head = discovery_body
                                    .pointer("/fields/facts/head_sha")
                                    .and_then(Value::as_str);
                                let number = discovery_body
                                    .pointer("/fields/facts/number")
                                    .and_then(Value::as_u64);
                                let kind = discovery_body
                                    .pointer("/fields/kind")
                                    .and_then(Value::as_str);
                                let repository_identity = current_object
                                    .get("repository_id")
                                    .filter(|value| !value.is_null())
                                    .cloned()
                                    .unwrap_or_else(|| Value::String(resource.into()));
                                let delivery_scope = subscription_subject
                                    .rsplit('/')
                                    .next()
                                    .expect("a subscription subject has a local name");
                                let delivery_key = if uses_collection {
                                    canonical_hash(&(
                                        mission,
                                        delivery_scope,
                                        repository_identity,
                                        kind,
                                        number,
                                        head,
                                    ))
                                } else {
                                    canonical_hash(&(subscription_subject, &discovery))
                                }
                                .map_err(internal)?;
                                if uses_collection
                                    && (collection_delivery_was_requested_tx(
                                        transaction,
                                        mission,
                                        delivery_scope,
                                        &delivery_resource,
                                        head,
                                        &delivery_key,
                                    )
                                    .map_err(internal)?
                                        || routed_to_owner_tx(transaction, &delivery_key)?)
                                {
                                    continue;
                                }
                                // An item that a live agent owns goes to that agent, and no
                                // review, triage, or person sees it.
                                let item_facts = &discovery_body["fields"]["facts"];
                                if uses_collection
                                    && subscription.owner_message
                                    && let Some((owner, why)) =
                                        item_owner_tx(transaction, item_facts).map_err(internal)?
                                {
                                    let (title, detail) = item_route_text(item_facts);
                                    message_subjects.extend(route_item_to_owner_tx(
                                        transaction,
                                        &self.origin,
                                        &batch_id,
                                        subscription_subject,
                                        &delivery_resource,
                                        &owner,
                                        &why,
                                        &title,
                                        &detail,
                                        &delivery_key,
                                        std::slice::from_ref(&discovery),
                                    )?);
                                    continue;
                                }
                                let mut request_fields = json!({
                                    "mission": format!("mission/{mission}"),
                                    "resource": delivery_resource,
                                    "resource_input": resource_input,
                                    "workspace": workspace,
                                    "discovery": discovery,
                                    "delivery_key": delivery_key,
                                });
                                if let Some(revision) = subscription.revision.as_deref() {
                                    request_fields
                                        .as_object_mut()
                                        .expect("subscription request fields are an object")
                                        .insert("mission_revision".into(), Value::String(revision.into()));
                                }
                                if let Some(requester) = subscription.requester.as_deref() {
                                    request_fields
                                        .as_object_mut()
                                        .expect("subscription request fields are an object")
                                        .insert("requester".into(), Value::String(requester.into()));
                                }
                                // A request cites the item version it was made for, so a checkpoint
                                // keeps that version while the request needs it.
                                let evidence = if uses_collection {
                                    vec![discovery.clone()]
                                } else {
                                    evidence.clone()
                                };
                                append_claim_tx(
                                    transaction,
                                    &self.origin,
                                    subscription_subject,
                                    "subscription.mission-requested",
                                    None,
                                    &json!({"fields": request_fields, "evidence": evidence}),
                                    &[],
                                    Some(&batch_id),
                                )
                                .map_err(claim_append_error)?;
                            }
                            continue;
                        }
                        let message_subject = format!("message/resource-{}", &stable[..20]);
                        let mut content = json!({
                            "resource": resource,
                            "observer": observer,
                            "changed_fields": selected,
                            "facts": repository_facts,
                        });
                        // A message names the items that changed, up to a bound; each item's
                        // resource holds the rest.
                        if !selected_items.is_empty() {
                            content["items"] = Value::Array(
                                selected_items
                                    .iter()
                                    .take(MESSAGE_ITEMS)
                                    .map(|(_, subject, _, facts)| {
                                        json!({"resource": subject, "facts": facts})
                                    })
                                    .collect(),
                            );
                            content["items_changed"] = Value::from(selected_items.len());
                        }
                        let content = serde_json::to_string(&content).map_err(internal)?;
                        let evidence = evidence
                            .iter()
                            .cloned()
                            .chain(
                                selected_items
                                    .iter()
                                    .take(MESSAGE_ITEMS)
                                    .map(|(_, _, claim, _)| claim.clone()),
                            )
                            .collect::<Vec<_>>();
                        append_claim_tx(
                            transaction,
                            &self.origin,
                            &message_subject,
                            "message.sent",
                            None,
                            &json!({"fields": {
                                "from": format!("daemon/{}", self.origin),
                                "to": subscription.to,
                                "title": format!("Resource changed: {resource}"),
                                "content": content,
                                "status": "sent",
                                "tags": ["resource-change", subscription_subject],
                            }, "evidence": evidence}),
                            &[],
                            Some(&batch_id),
                        )
                        .map_err(claim_append_error)?;
                        message_subjects.push(message_subject);
                    }
                }
                let outcome = ResourceObservationOutcome {
                    baseline,
                    changed_fields,
                    observation_claim: observation_claim.map(|claim| claim.id),
                    message_subjects,
                };
                transaction
                    .execute(
                        "INSERT INTO idempotency(operation_id, response) VALUES (?1, ?2)",
                        params![
                            opaque_cache_key(&idempotency_key),
                            serde_json::to_string(&outcome).map_err(internal)?
                        ],
                    )
                    .map_err(internal)?;
                Ok(outcome)
            })
            .map_err(|error| St3Error::new("internal", error))?
    }

    /// Every mission request that a subscription recorded, oldest first, with its disposition.
    pub fn subscription_requests(
        &self,
        subscription: &str,
    ) -> Result<Vec<SubscriptionRequestView>> {
        let mut decisions = self.claims_for(subscription, Some("subscription.mission-started"))?;
        for kind in [
            "subscription.mission-request-cancelled",
            "subscription.mission-request-released",
            "subscription.mission-failed",
        ] {
            decisions.extend(self.claims_for(subscription, Some(kind))?);
        }
        Ok(self
            .claims_for(subscription, Some("subscription.mission-requested"))?
            .into_iter()
            .map(|request| subscription_request_view(&request, &decisions))
            .collect())
    }

    /// Release a held subscription request, or cancel a pending or held one, as a person or an
    /// agent.
    pub fn decide_subscription_request(
        &self,
        request: &str,
        decision: &str,
        input: &SubscriptionRequestDecision,
    ) -> Result<SubscriptionRequestView, St3Error> {
        if !(input.actor.starts_with("person/") || input.actor.starts_with("agent/")) {
            return Err(St3Error::new(
                "invalid-subscription-request-actor",
                "a subscription request decision needs a person or agent actor",
            ));
        }
        if input.reason.trim().is_empty() {
            return Err(St3Error::new(
                "missing-subscription-request-reason",
                "a subscription request decision needs a reason",
            ));
        }
        let claim = self
            .claim_by_id(request)
            .map_err(internal)?
            .filter(|claim| claim.kind == "subscription.mission-requested")
            .ok_or_else(|| {
                St3Error::new(
                    "missing-subscription-request",
                    format!("subscription request `{request}` does not exist"),
                )
            })?;
        let view = |store: &Self| -> Result<SubscriptionRequestView, St3Error> {
            store
                .subscription_requests(&claim.subject)
                .map_err(internal)?
                .into_iter()
                .find(|view| view.request == claim.id)
                .ok_or_else(|| St3Error::new("internal", "the subscription request vanished"))
        };
        if self
            .operation_claim(&input.idempotency_key)
            .map_err(internal)?
            .is_some()
        {
            return view(self);
        }
        let current = view(self)?;
        let kind = match (decision, current.status.as_str()) {
            ("cancel", "pending" | "held") => "subscription.mission-request-cancelled",
            ("release", "held") => "subscription.mission-request-released",
            ("cancel" | "release", status) => {
                return Err(St3Error::new(
                    "subscription-request-not-open",
                    format!("subscription request `{request}` is {status}"),
                ));
            }
            (decision, _) => {
                return Err(St3Error::new(
                    "invalid-subscription-request-decision",
                    format!("`{decision}` is not a subscription request decision"),
                ));
            }
        };
        self.append_claim(&ClaimInput {
            subject: claim.subject.clone(),
            kind: kind.into(),
            actor: Some(input.actor.clone()),
            fields: BTreeMap::from([
                ("request".into(), Value::String(claim.id.clone())),
                ("reason".into(), Value::String(input.reason.clone())),
            ]),
            evidence: vec![claim.id.clone()],
            expected_subject: None,
            idempotency_key: Some(input.idempotency_key.clone()),
        })?;
        view(self)
    }

    pub fn pending_subscription_mission_requests(&self, subject: &str) -> Result<Vec<ClaimRecord>> {
        smallclaims::touched::note_read(|| subject.to_owned());
        let connection = self.readers.get();
        // Every pass asks this for every subscription. The finished requests are listed once, not
        // scanned for each request: a correlated NOT EXISTS read every finished claim once per
        // request, 0.4 s a pass for a subscription with hundreds of runs.
        let mut statement = connection.prepare(&canonical_sql(
            "SELECT request.id, request.store_index, request.batch_id, request.subject,
                    request.kind, request.origin, request.actor, request.body,
                    request.predecessors, request.accepted_at_unix_ms
             FROM claims AS request
             WHERE request.subject=?1 AND request.kind='subscription.mission-requested'
               AND request.id NOT IN (
                 SELECT json_extract(finished.body, '$.fields.request') FROM claims AS finished
                 WHERE finished.subject=?1
                   AND finished.kind IN (
                     'subscription.mission-started',
                     'subscription.mission-failed',
                     'subscription.mission-request-cancelled'
                   )
                   AND json_extract(finished.body, '$.fields.request') IS NOT NULL
               )
             ORDER BY CANONICAL_ASC(request)",
        ))?;
        statement
            .query_map([subject], claim_from_row)?
            .collect::<Result<Vec<_>, _>>()
            .map_err(Into::into)
    }

    /// Find a mission-run PR resource for this discovered PR when that run already has a human
    /// review gate for its own PR. Intake uses this graph provenance to avoid a second reviewer.
    /// Why a pull request review that has not started must not start: since the request, its
    /// pull request closed or merged, went back to draft, or moved to a newer head. `None` while
    /// the requested head is still the open pull request's current head.
    pub fn stale_pull_request_request(
        &self,
        resource: &str,
        discovery: &str,
    ) -> Result<Option<String>> {
        let Some(requested) = self.claim_by_id(discovery)? else {
            return Ok(None);
        };
        let Some(current) = self
            .latest_actual_value(resource)?
            .and_then(|actual| actual.get("facts").cloned())
        else {
            return Ok(None);
        };
        let number = current
            .get("number")
            .and_then(Value::as_u64)
            .map_or_else(|| resource.to_owned(), |number| format!("#{number}"));
        if let Some(state) = current
            .get("state")
            .and_then(Value::as_str)
            .filter(|state| *state != "open")
        {
            return Ok(Some(format!("pull request {number} is {state}")));
        }
        if current.get("draft").and_then(Value::as_bool) == Some(true) {
            return Ok(Some(format!("pull request {number} is a draft again")));
        }
        let short = |head: &str| head.chars().take(12).collect::<String>();
        let requested_head = match requested
            .body
            .pointer("/fields/facts/head_sha")
            .and_then(Value::as_str)
        {
            Some(head) => Some(head.to_owned()),
            None => listed_head_tx(&self.readers.get(), Some(&requested.body))?,
        };
        let current_head = current.get("head_sha").and_then(Value::as_str);
        if let (Some(requested_head), Some(current_head)) =
            (requested_head.as_deref(), current_head)
            && requested_head != current_head
        {
            return Ok(Some(format!(
                "pull request {number} moved from head {} to {}",
                short(requested_head),
                short(current_head)
            )));
        }
        Ok(None)
    }

    /// Unstarted ref deliveries collapse to the latest observed head. Running missions
    /// retain their pinned discovery and exact CI gate, even when the ref moves again.
    pub fn stale_ref_request(&self, resource: &str, discovery: &str) -> Result<Option<String>> {
        stale_ref_request_tx(&self.readers.get(), resource, discovery)
    }

    pub fn authoring_review_owner(&self, discovery: &str) -> Result<Option<String>> {
        let Some(claim) = self.claim_by_id(discovery)? else {
            return Ok(None);
        };
        let Some(facts) = claim.body.pointer("/fields/facts") else {
            return Ok(None);
        };
        let candidates = authoring_pull_request_runs_tx(&self.readers.get(), facts)?;
        for run in candidates {
            let resource = format!("resource/{run}/pull-request");
            let run_id = run.strip_prefix("mission-run/").unwrap_or(&run);
            let Some(run) = self.mission_run(run_id)? else {
                continue;
            };
            let mission_id = run.mission.strip_prefix("mission/").unwrap_or(&run.mission);
            let Some(mission) = self.mission_spec(mission_id, Some(&run.revision))? else {
                continue;
            };
            let has_own_review = mission.steps.values().any(|step| {
                step.gates.iter().any(|gate| match gate {
                    crate::model::GateSpec::Human { review_targets, .. } => review_targets
                        .iter()
                        .any(|target| target == &resource || target.ends_with("/pull-request")),
                    _ => false,
                })
            });
            if has_own_review {
                return Ok(Some(format!("mission-run/{run_id}")));
            }
        }
        Ok(None)
    }

    /// Read only one pending request's retry history. The request index covers the count and
    /// locates its newest deadline without materializing every deferral on the subscription.
    pub fn subscription_mission_deferral(
        &self,
        subject: &str,
        request: &str,
    ) -> Result<Option<(u128, u32)>> {
        let connection = self.readers.get();
        let local: Option<(i64, u32)> = connection
            .query_row(
                "SELECT not_before_unix_ms, attempts
                 FROM local_subscription_mission_deferrals
                 WHERE subject=?1 AND request=?2",
                params![subject, request],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .optional()?;
        if let Some((deadline, attempts)) = local {
            return Ok(Some((deadline as u128, attempts)));
        }
        let count: u32 = connection.query_row(
            "SELECT COUNT(*) FROM claims
             WHERE subject=?1 AND kind='subscription.mission-deferred'
               AND json_extract(body, '$.fields.request')=?2",
            params![subject, request],
            |row| row.get(0),
        )?;
        if count == 0 {
            return Ok(None);
        }
        let deadline: Option<u64> = connection.query_row(
            &canonical_sql(
                "SELECT CAST(json_extract(body, '$.fields.not_before_unix_ms') AS INTEGER)
             FROM claims
             WHERE subject=?1 AND kind='subscription.mission-deferred'
               AND json_extract(body, '$.fields.request')=?2
             ORDER BY CANONICAL_DESC(claims) LIMIT 1",
            ),
            params![subject, request],
            |row| row.get(0),
        )?;
        Ok(deadline.map(|deadline| (u128::from(deadline), count)))
    }

    pub fn record_subscription_mission_deferral(
        &self,
        subject: &str,
        request: &str,
        deadline: u128,
        attempts: u32,
    ) -> Result<()> {
        let deadline = i64::try_from(deadline)?;
        self.connection
            .batched(|transaction| {
                transaction.execute(
                    "INSERT INTO local_subscription_mission_deferrals
                         (subject, request, not_before_unix_ms, attempts)
                     VALUES (?1, ?2, ?3, ?4)
                     ON CONFLICT(subject, request) DO UPDATE SET
                         not_before_unix_ms=excluded.not_before_unix_ms,
                         attempts=excluded.attempts",
                    params![subject, request, deadline, attempts],
                )
            })
            .map_err(anyhow::Error::msg)??;
        Ok(())
    }

    pub fn pending_schedule_work_requests(&self, subject: &str) -> Result<Vec<ClaimRecord>> {
        let connection = self.readers.get();
        let mut statement = connection.prepare(&canonical_sql(
            "SELECT request.id, request.store_index, request.batch_id, request.subject,
                    request.kind, request.origin, request.actor, request.body,
                    request.predecessors, request.accepted_at_unix_ms
             FROM claims AS request
             WHERE request.subject=?1 AND request.kind='schedule.work-requested'
               AND request.id NOT IN (
                 SELECT json_extract(closed.body, '$.fields.request') FROM claims AS closed
                 WHERE closed.subject=?1
                   AND closed.kind IN ('schedule.work-started','schedule.work-failed')
                   AND json_extract(closed.body, '$.fields.request') IS NOT NULL
               )
             ORDER BY CANONICAL_ASC(request)",
        ))?;
        statement
            .query_map([subject], claim_from_row)?
            .collect::<Result<Vec<_>, _>>()
            .map_err(Into::into)
    }

    pub fn schedule_work_start_for_request(
        &self,
        subject: &str,
        request: &str,
    ) -> Result<Option<ClaimRecord>> {
        let connection = self.readers.get();
        connection
            .query_row(
                &canonical_sql(
                    "SELECT id, store_index, batch_id, subject, kind, origin, actor, body,
                        predecessors, accepted_at_unix_ms
                 FROM claims WHERE subject=?1 AND kind='schedule.work-started'
                   AND json_extract(body, '$.fields.request')=?2
                 ORDER BY CANONICAL_DESC(claims) LIMIT 1",
                ),
                params![subject, request],
                claim_from_row,
            )
            .optional()
            .map_err(Into::into)
    }

    pub fn schedule_has_active_started_run(&self, subject: &str) -> Result<bool> {
        let connection = self.readers.get();
        connection
            .query_row(
                "SELECT EXISTS(
                   SELECT 1 FROM claims AS started
                   JOIN mission_runs AS run
                     ON json_extract(started.body, '$.fields.mission_run')='mission-run/' || run.id
                   WHERE started.subject=?1 AND started.kind='schedule.work-started'
                     AND run.status NOT IN ('completed','cancelled','failed')
                 )",
                [subject],
                |row| row.get(0),
            )
            .map_err(Into::into)
    }

    /// Aggregate durable provider usage without mixing context-window occupancy
    /// with spend. Per incarnation, a cumulative total wins over response
    /// deltas; otherwise the non-overlapping response deltas are summed.
    pub fn usage_summary_at(
        &self,
        subject: &str,
        incarnation: Option<&str>,
        at_index: Option<u64>,
    ) -> Result<Option<UsageSummary>> {
        let connection = self.readers.get();
        let at_index = at_index.unwrap_or(i64::MAX as u64);
        let mut statement = connection.prepare(&canonical_sql(
            "SELECT store_index, body, accepted_at_unix_ms FROM claims
             WHERE subject=?1 AND kind='harness.usage' AND store_index<=?2
             ORDER BY CANONICAL_ASC(claims)",
        ))?;
        let rows = statement.query_map(params![subject, at_index], |row| {
            Ok((
                row.get::<_, u64>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
            ))
        })?;
        Self::usage_summary_from_rows(rows, incarnation)
    }

    /// Fetch usage for a bounded resource page with one SQL read per SQLite
    /// parameter chunk, then apply the same reduction as a detail read.
    pub fn usage_summaries_at(
        &self,
        subjects: &[String],
        at_index: Option<u64>,
    ) -> Result<BTreeMap<String, UsageSummary>> {
        let connection = self.readers.get();
        let mut grouped = BTreeMap::<String, Vec<rusqlite::Result<(u64, String, String)>>>::new();
        let unique_subjects = subjects
            .iter()
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect::<Vec<_>>();
        for chunk in unique_subjects.chunks(500) {
            if chunk.is_empty() {
                continue;
            }
            let placeholders = vec!["?"; chunk.len()].join(",");
            let sql = canonical_sql(&format!(
                "SELECT subject, store_index, body, accepted_at_unix_ms FROM claims
                 WHERE kind='harness.usage' AND store_index<={} AND subject IN ({placeholders})
                 ORDER BY subject, CANONICAL_ASC(claims)",
                at_index.unwrap_or(i64::MAX as u64)
            ));
            let mut statement = connection.prepare(&sql)?;
            for row in statement.query_map(rusqlite::params_from_iter(chunk), |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, u64>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, String>(3)?,
                ))
            })? {
                let (subject, index, body, accepted) = row?;
                grouped
                    .entry(subject)
                    .or_default()
                    .push(Ok((index, body, accepted)));
            }
        }
        let mut summaries = BTreeMap::new();
        for (subject, rows) in grouped {
            if let Some(summary) = Self::usage_summary_from_rows(rows, None)? {
                summaries.insert(subject, summary);
            }
        }
        Ok(summaries)
    }

    fn usage_summary_from_rows<I>(
        rows: I,
        incarnation: Option<&str>,
    ) -> Result<Option<UsageSummary>>
    where
        I: IntoIterator<Item = rusqlite::Result<(u64, String, String)>>,
    {
        #[derive(Default)]
        struct Spend {
            cumulative: Option<CumulativeUsage>,
            rollups: BTreeMap<String, (u64, u64, u64, u64, u64)>,
            response_total: u64,
            response_input: u64,
            response_output: u64,
            response_cached: u64,
            response_cost: f64,
            response_has_cost: bool,
            response_currency: Option<String>,
        }

        let mut spend = BTreeMap::<String, Spend>::new();
        let mut context = None::<(u64, ContextUsage)>;
        let mut saw = false;
        for row in rows {
            let (store_index, body, accepted_at) = row?;
            let body: Value = serde_json::from_str(&body)?;
            let fields = body.get("fields").unwrap_or(&body);
            let claim_incarnation = fields
                .get("incarnation_id")
                .and_then(Value::as_str)
                .unwrap_or("unknown");
            if incarnation.is_some_and(|expected| expected != claim_incarnation) {
                continue;
            }
            saw = true;
            match fields.get("semantics").and_then(Value::as_str) {
                Some("context_occupancy") => {
                    context = Some((
                        store_index,
                        ContextUsage {
                            used_tokens: fields.get("context_used_tokens").and_then(Value::as_u64),
                            window_tokens: fields
                                .get("context_window_tokens")
                                .and_then(Value::as_u64),
                            used_percent: fields
                                .get("context_used_percent")
                                .and_then(Value::as_f64),
                            model: fields
                                .get("model")
                                .and_then(Value::as_str)
                                .map(str::to_owned),
                            compactions: fields
                                .get("compactions")
                                .and_then(Value::as_u64)
                                .unwrap_or(0),
                            last_compaction_ms: fields
                                .get("last_compaction_ms")
                                .and_then(Value::as_u64),
                            last_compaction_trigger: fields
                                .get("last_compaction_trigger")
                                .and_then(Value::as_str)
                                .map(str::to_owned),
                            observed_at_unix_ms: accepted_at.parse().unwrap_or_default(),
                        },
                    ));
                }
                Some("session_cumulative") => {
                    let Some(total) = fields.get("total_tokens").and_then(Value::as_u64) else {
                        continue;
                    };
                    let candidate = (
                        total,
                        fields
                            .get("input_tokens")
                            .and_then(Value::as_u64)
                            .unwrap_or(0),
                        fields
                            .get("output_tokens")
                            .and_then(Value::as_u64)
                            .unwrap_or(0),
                        fields
                            .get("cached_tokens")
                            .and_then(Value::as_u64)
                            .unwrap_or(0),
                        fields.get("cost").and_then(Value::as_f64),
                        fields
                            .get("currency")
                            .and_then(Value::as_str)
                            .map(str::to_owned),
                    );
                    let group = spend.entry(claim_incarnation.to_owned()).or_default();
                    if group
                        .cumulative
                        .as_ref()
                        .is_none_or(|current| candidate.0 >= current.0)
                    {
                        group.cumulative = Some(candidate);
                    }
                }
                Some("response_rollup") => {
                    let group = spend.entry(claim_incarnation.to_owned()).or_default();
                    let key = ["model", "account", "owner_run", "owner_step", "host"]
                        .iter()
                        .map(|key| fields.get(*key).and_then(Value::as_str).unwrap_or(""))
                        .collect::<Vec<_>>()
                        .join("\0");
                    group.rollups.insert(
                        key,
                        (
                            fields
                                .get("total_tokens")
                                .and_then(Value::as_u64)
                                .unwrap_or(0),
                            fields
                                .get("input_tokens")
                                .and_then(Value::as_u64)
                                .unwrap_or(0),
                            fields
                                .get("output_tokens")
                                .and_then(Value::as_u64)
                                .unwrap_or(0),
                            fields
                                .get("cache_write_tokens")
                                .and_then(Value::as_u64)
                                .unwrap_or(0),
                            fields
                                .get("cached_tokens")
                                .and_then(Value::as_u64)
                                .unwrap_or(0),
                        ),
                    );
                }
                Some("response") => {
                    let Some(total) = fields.get("total_tokens").and_then(Value::as_u64) else {
                        continue;
                    };
                    let group = spend.entry(claim_incarnation.to_owned()).or_default();
                    group.response_total = group.response_total.saturating_add(total);
                    group.response_input = group.response_input.saturating_add(
                        fields
                            .get("input_tokens")
                            .and_then(Value::as_u64)
                            .unwrap_or(0),
                    );
                    group.response_output = group.response_output.saturating_add(
                        fields
                            .get("output_tokens")
                            .and_then(Value::as_u64)
                            .unwrap_or(0),
                    );
                    group.response_cached = group.response_cached.saturating_add(
                        fields
                            .get("cached_tokens")
                            .and_then(Value::as_u64)
                            .unwrap_or(0),
                    );
                    if let Some(cost) = fields.get("cost").and_then(Value::as_f64) {
                        group.response_cost += cost;
                        group.response_has_cost = true;
                    }
                    if let Some(currency) = fields.get("currency").and_then(Value::as_str) {
                        group.response_currency = Some(currency.to_owned());
                    }
                }
                _ => {}
            }
        }
        if !saw {
            return Ok(None);
        }
        let mut summary = UsageSummary {
            aggregation: "cumulative-per-incarnation-else-response-deltas".into(),
            context: context.map(|(_, value)| value),
            ..UsageSummary::default()
        };
        let mut cost = 0.0;
        let mut has_cost = false;
        for group in spend.into_values() {
            summary.incarnation_count += 1;
            if !group.rollups.is_empty() {
                for (total, input, output, writes, reads) in group.rollups.into_values() {
                    summary.total_tokens = summary.total_tokens.saturating_add(total);
                    summary.input_tokens = summary.input_tokens.saturating_add(input);
                    summary.output_tokens = summary.output_tokens.saturating_add(output);
                    summary.cache_write_tokens = summary.cache_write_tokens.saturating_add(writes);
                    summary.cached_tokens = summary.cached_tokens.saturating_add(reads);
                }
            } else if let Some((total, input, output, cached, group_cost, currency)) =
                group.cumulative
            {
                summary.total_tokens = summary.total_tokens.saturating_add(total);
                summary.input_tokens = summary.input_tokens.saturating_add(input);
                summary.output_tokens = summary.output_tokens.saturating_add(output);
                summary.cached_tokens = summary.cached_tokens.saturating_add(cached);
                if let Some(value) = group_cost {
                    cost += value;
                    has_cost = true;
                }
                summary.currency = summary.currency.or(currency);
            } else {
                summary.total_tokens = summary.total_tokens.saturating_add(group.response_total);
                summary.input_tokens = summary.input_tokens.saturating_add(group.response_input);
                summary.output_tokens = summary.output_tokens.saturating_add(group.response_output);
                summary.cached_tokens = summary.cached_tokens.saturating_add(group.response_cached);
                if group.response_has_cost {
                    cost += group.response_cost;
                    has_cost = true;
                }
                summary.currency = summary.currency.or(group.response_currency);
            }
        }
        summary.cost = has_cost.then_some(cost);
        Ok(Some(summary))
    }

    /// Period spend from replicated cumulative snapshots. The snapshot immediately before the
    /// start is the baseline, so a long-lived incarnation only contributes spend in the period.
    /// Each row is one agent incarnation's spend on one model and account for one mission run
    /// and step on one host, with its API-equivalent cost in millionths of a dollar. Tokens no
    /// price covers are counted in `unpriced_tokens`, never as free.
    pub fn usage_period_rows(&self, since_ms: u64, until_ms: u64) -> Result<Vec<Value>> {
        const BUCKETS: [&str; 9] = [
            "total_tokens",
            "input_tokens",
            "output_tokens",
            "cache_write_tokens",
            "cache_write_1h_tokens",
            "cached_tokens",
            "cost_microusd",
            "reported_cost_microusd",
            "unpriced_tokens",
        ];
        #[derive(Clone, Copy, Default)]
        struct Snapshot {
            at: u64,
            buckets: [u64; BUCKETS.len()],
        }
        let connection = self.readers.get();
        let mut statement = connection.prepare(&canonical_sql(
            "SELECT subject, store_index, body FROM claims WHERE kind='harness.usage'
             AND json_extract(body, '$.fields.semantics')='response_rollup'
             ORDER BY CANONICAL_ASC(claims)",
        ))?;
        let rows = statement.query_map([], |row| {
            Ok((
                row.get::<_, String>(0)?,
                row.get::<_, u64>(1)?,
                row.get::<_, String>(2)?,
            ))
        })?;
        type Key = (String, String, String, String, String, String, String);
        let mut groups = BTreeMap::<Key, (Option<Snapshot>, Option<Snapshot>, String)>::new();
        for row in rows {
            let (subject, _index, body) = row?;
            let body: Value = serde_json::from_str(&body)?;
            let fields = &body["fields"];
            let at = fields["observed_at_unix_ms"].as_u64().unwrap_or(0);
            if at > until_ms {
                continue;
            }
            let mut snapshot = Snapshot {
                at,
                ..Snapshot::default()
            };
            for (bucket, name) in snapshot.buckets.iter_mut().zip(BUCKETS) {
                *bucket = fields[name].as_u64().unwrap_or(0);
            }
            // A rollup from before costs were recorded priced nothing: its tokens are unpriced.
            if fields.get("cost_microusd").is_none() {
                snapshot.buckets[8] = snapshot.buckets[0];
            }
            let text = |name| fields[name].as_str().unwrap_or("").to_owned();
            let key = (
                subject,
                text("incarnation_id"),
                text("model"),
                text("account"),
                text("owner_run"),
                text("owner_step"),
                text("host"),
            );
            let (baseline, latest, pricing) = groups.entry(key).or_default();
            let target = if at <= since_ms { baseline } else { latest };
            if target.is_none_or(|previous| at >= previous.at) {
                *target = Some(snapshot);
                if at > since_ms {
                    *pricing = text("pricing");
                }
            }
        }
        let mut result = Vec::new();
        for (
            (agent, _incarnation, model, account, mission_run, step, host),
            (baseline, latest, pricing),
        ) in groups
        {
            let Some(latest) = latest else {
                continue;
            };
            // A series that went backwards restarted from zero, for example when a node's local
            // totals were rebuilt; everything after the restart is spend in the period.
            let baseline = baseline
                .filter(|baseline| baseline.buckets[0] <= latest.buckets[0])
                .unwrap_or_default();
            let mut row = json!({
                "agent": agent, "mission_run": mission_run, "step": step,
                "model": model, "account": account, "host": host,
                "pricing": pricing,
            });
            for (index, name) in BUCKETS.iter().enumerate() {
                row[*name] =
                    Value::from(latest.buckets[index].saturating_sub(baseline.buckets[index]));
            }
            if row["total_tokens"] == 0 {
                continue;
            }
            result.push(row);
        }
        result.sort_by(|a, b| b["total_tokens"].as_u64().cmp(&a["total_tokens"].as_u64()));
        Ok(result)
    }

    /// Bounded claim history for one subject/kind projection, backed by the composite index.
    pub fn claims_for_subject_kind_at(
        &self,
        subject: &str,
        kind: &str,
        before_index: Option<u64>,
        descending: bool,
        limit: usize,
    ) -> Result<ClaimsPage> {
        let connection = self.readers.get();
        let order = if descending { "DESC" } else { "ASC" };
        let query = format!(
            "SELECT id, store_index, batch_id, subject, kind, origin, actor, body, predecessors, accepted_at_unix_ms
             FROM claims WHERE subject=?1 AND kind=?2 AND (?3 IS NULL OR store_index<?3)
             ORDER BY store_index {order} LIMIT ?4"
        );
        let mut statement = connection.prepare(&query)?;
        let rows = statement.query_map(
            params![subject, kind, before_index, limit.saturating_add(1) as u64],
            claim_from_row,
        )?;
        let mut claims = rows.collect::<rusqlite::Result<Vec<_>>>()?;
        let next_cursor = if claims.len() > limit {
            claims.pop();
            claims.last().map(|claim| claim.store_index)
        } else {
            None
        };
        Ok(ClaimsPage {
            claims,
            next_cursor,
        })
    }

    /// Bounded timeline history for exactly one runtime incarnation. The
    /// expression index keeps old incarnations from consuming the page bound.
    /// The page merges replicated timeline claims, which older builds wrote, with
    /// this node's local timeline observations; a local observation sorts after the
    /// claim it follows.
    pub fn timeline_claims_for_incarnation_at(
        &self,
        subject: &str,
        incarnation: &str,
        before_index: Option<u64>,
        descending: bool,
        limit: usize,
    ) -> Result<ClaimsPage> {
        let claims = self.timeline_claim_rows_for_incarnation_at(
            subject,
            incarnation,
            before_index,
            descending,
            limit,
        )?;
        let local = {
            let connection = self.readers.get();
            let order = if descending { "DESC" } else { "ASC" };
            let mut statement = connection.prepare(&format!(
                "{LOCAL_OBSERVATION_COLUMNS}
                 WHERE subject=?1 AND kind='harness.timeline'
                   AND json_extract(body, '$.fields.incarnation_id')=?2
                   AND (?3 IS NULL OR after_store_index<?3)
                 ORDER BY id {order} LIMIT ?4"
            ))?;
            let rows = statement.query_map(
                params![
                    subject,
                    incarnation,
                    before_index,
                    limit.saturating_add(1) as u64
                ],
                |row| local_observation_from_row(&self.origin, row),
            )?;
            rows.collect::<rusqlite::Result<Vec<_>>>()?
        };
        let mut merged = claims.claims;
        merged.extend(local);
        merged.sort_by_key(claim_log_order);
        if descending {
            merged.reverse();
        }
        let more = claims.next_cursor.is_some() || merged.len() > limit;
        merged.truncate(limit);
        let next_cursor = more
            .then(|| merged.last().map(|claim| claim.store_index))
            .flatten();
        Ok(ClaimsPage {
            claims: merged,
            next_cursor,
        })
    }

    /// The newest local timeline observation for one incarnation at or before a snapshot.
    pub fn latest_local_timeline_at(
        &self,
        subject: &str,
        incarnation: &str,
        snapshot_index: u64,
    ) -> Result<Option<u128>> {
        let connection = self.readers.get();
        connection
            .query_row(
                "SELECT observed_at_unix_ms FROM local_observations
                 WHERE subject=?1 AND kind='harness.timeline'
                   AND json_extract(body, '$.fields.incarnation_id')=?2
                   AND after_store_index<=?3
                 ORDER BY id DESC LIMIT 1",
                params![subject, incarnation, snapshot_index],
                |row| row.get::<_, i64>(0),
            )
            .optional()
            .map(|value| value.map(|value| value.max(0) as u128))
            .map_err(Into::into)
    }

    /// The earliest and latest acceptance times of the claims about `subject` that belong to one
    /// runtime: those that name `incarnation`, or, for a runtime without one, those that name
    /// `runtime`. Only claims at or before `through` count, and when `through_claim` names one of
    /// the subject's claims, only those up to it. An incarnation takes two index seeks however
    /// many claims the subject has; a runtime without one reads the subject's claims.
    pub fn runtime_claim_span_at(
        &self,
        subject: &str,
        incarnation: Option<&str>,
        runtime: Option<&str>,
        through: u64,
        through_claim: Option<&str>,
    ) -> Result<Option<(u128, u128)>> {
        let connection = self.readers.get();
        let through = match through_claim {
            Some(claim) => connection
                .prepare_cached("SELECT store_index FROM claims WHERE id=?1")?
                .query_row([claim], |row| row.get::<_, u64>(0))
                .optional()?
                .map_or(through, |index| index.min(through)),
            None => through,
        };
        let accepted = |text: String| text.parse::<u128>().unwrap_or_default();
        if let Some(incarnation) = incarnation {
            let mut span = [None, None];
            for (slot, order) in span.iter_mut().zip(["ASC", "DESC"]) {
                *slot = connection
                    .prepare_cached(&incarnation_claim_time_query(order))?
                    .query_row(params![subject, incarnation, through], |row| {
                        row.get::<_, String>(0)
                    })
                    .optional()?
                    .map(accepted);
            }
            return Ok(span[0].zip(span[1]));
        }
        let Some(runtime) = runtime else {
            return Ok(None);
        };
        let mut statement = connection.prepare_cached(
            "SELECT accepted_at_unix_ms FROM claims
             WHERE subject=?1 AND store_index<=?3
               AND json_extract(body, CASE WHEN json_type(body, '$.fields') IS NULL
                   THEN '$.runtime_id' ELSE '$.fields.runtime_id' END)=?2",
        )?;
        let mut span = None::<(u128, u128)>;
        for time in statement.query_map(params![subject, runtime, through], |row| {
            row.get::<_, String>(0)
        })? {
            let time = accepted(time?);
            span = Some(span.map_or((time, time), |(first, last)| {
                (first.min(time), last.max(time))
            }));
        }
        Ok(span)
    }

    /// Last substantive activity for an agent, excluding heartbeat and usage observations.
    pub fn agent_last_activity_at(
        &self,
        agent: &str,
        incarnation: Option<&str>,
        snapshot_index: u64,
    ) -> Result<Option<u128>> {
        let connection = self.readers.get();
        let mut times = Vec::new();
        if let Some(incarnation) = incarnation {
            let local: Option<i64> = connection.query_row(
                "SELECT observed_at_unix_ms FROM local_observations
                 WHERE subject=?1 AND kind='harness.timeline'
                   AND json_extract(body, '$.fields.incarnation_id')=?2
                   AND json_extract(body, '$.fields.entry_type') IN ('message','content','tool_call','tool_result')
                   AND after_store_index<=?3 ORDER BY id DESC LIMIT 1",
                params![agent, incarnation, snapshot_index], |row| row.get(0),
            ).optional()?;
            if let Some(time) = local {
                times.push(time.max(0) as u128);
            }
            let replicated: Option<String> = connection.query_row(
                "SELECT accepted_at_unix_ms FROM claims
                 WHERE subject=?1 AND kind='harness.timeline'
                   AND json_extract(body, '$.fields.incarnation_id')=?2
                   AND json_extract(body, '$.fields.entry_type') IN ('message','content','tool_call','tool_result')
                   AND store_index<=?3 ORDER BY store_index DESC LIMIT 1",
                params![agent, incarnation, snapshot_index], |row| row.get(0),
            ).optional()?;
            times.extend(replicated.and_then(|time| time.parse::<u128>().ok()));
        }
        for query in [
            "SELECT accepted_at_unix_ms FROM claims WHERE actor=?1 AND kind IN ('work.progress','work.submitted') AND store_index<=?2 ORDER BY store_index DESC LIMIT 1",
            "SELECT accepted_at_unix_ms FROM claims WHERE kind='message.sent' AND json_extract(body, '$.fields.from')=?1 AND store_index<=?2 ORDER BY store_index DESC LIMIT 1",
            "SELECT accepted_at_unix_ms FROM claims WHERE kind='message.sent' AND json_extract(body, '$.fields.to')=?1 AND store_index<=?2 ORDER BY store_index DESC LIMIT 1",
        ] {
            let time: Option<String> = connection
                .query_row(query, params![agent, snapshot_index], |row| row.get(0))
                .optional()?;
            times.extend(time.and_then(|time| time.parse::<u128>().ok()));
        }
        Ok(times.into_iter().max())
    }

    pub fn agent_working_since(
        &self,
        agent: &str,
        incarnation: &str,
        snapshot_index: u64,
    ) -> Result<Option<u128>> {
        let connection = self.readers.get();
        // The first `working` observation after the incarnation's last other state, in canonical
        // order, so every node that holds the same claims agrees.
        let mut statement = connection.prepare_cached(&format!(
            "SELECT json_extract(claims.body, '$.fields.state'), claims.accepted_at_unix_ms
             FROM claims JOIN batches ON batches.id=claims.batch_id
             WHERE claims.subject=?1 AND claims.kind='harness.observed'
               AND json_extract(claims.body, '$.fields.incarnation_id')=?2
               AND claims.store_index<=?3
             ORDER BY {CANONICAL_ORDER}"
        ))?;
        let states = statement
            .query_map(params![agent, incarnation, snapshot_index], |row| {
                Ok((row.get::<_, Option<String>>(0)?, row.get::<_, String>(1)?))
            })?
            .collect::<rusqlite::Result<Vec<_>>>()?;
        let after = states
            .iter()
            .rposition(|(state, _)| state.as_deref().is_some_and(|state| state != "working"))
            .map_or(0, |position| position + 1);
        Ok(states[after..]
            .iter()
            .find(|(state, _)| state.as_deref() == Some("working"))
            .and_then(|(_, time)| time.parse().ok()))
    }

